package com.rapidursa.mounts;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class RapidUrsaMountsPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(RapidUrsaMountsPlugin.class);
        RuneLite.main(args);
    }
}

package com.rapidursa.mounts;

import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;

final class FrozenAnimationController extends AnimationController
{
    FrozenAnimationController(Client client, Animation animation, int frame)
    {
        super(client, animation);
        setFrame(frame);
    }

    @Override
    public void tick(int ticks)
    {
        // The Wide riding pose deliberately holds frame 32.
    }
}

package com.rapidursa.mounts;

import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;

/**
 * Applies a skeletal animation before NPC-definition scaling. Newer Maya-style
 * animations may contain absolute bone translations and deform if their base
 * vertices are scaled first.
 */
final class PostScaleAnimationController extends AnimationController
{
    private final int scaleX;
    private final int scaleY;
    private final int scaleZ;

    PostScaleAnimationController(Client client, int animationId, int scaleX, int scaleY, int scaleZ)
    {
        super(client, animationId);
        this.scaleX = scaleX;
        this.scaleY = scaleY;
        this.scaleZ = scaleZ;
    }

    @Override
    public Model animate(Model model, AnimationController other)
    {
        Model animated = super.animate(model, other);
        return animated == null ? null : animated.scale(scaleX, scaleY, scaleZ);
    }
}

package com.rapidursa.mounts;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
final class BattleReadyOverlay extends Overlay implements MouseListener
{
    private final ClientThread clientThread;
    private final RapidUrsaMountsConfig config;
    private RapidUrsaMountsPlugin plugin;

    @Inject
    BattleReadyOverlay(ClientThread clientThread, RapidUrsaMountsConfig config)
    {
        this.clientThread = clientThread;
        this.config = config;
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPosition(OverlayPosition.TOP_LEFT);
    }

    void bind(RapidUrsaMountsPlugin plugin)
    {
        this.plugin = plugin;
    }

    void unbind()
    {
        plugin = null;
    }

    private boolean isAvailable()
    {
        return plugin != null && plugin.isMounted() && config.enabled()
            && config.mountType() == MountType.TERRORBIRD
            && config.ridingPose() == RidingPose.STANDARD;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!isAvailable())
        {
            return null;
        }

        int size = Math.max(24, Math.min(96, config.buttonSize()));
        int radius = Math.max(7, size / 5);
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
            RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setColor(new Color(18, 20, 24, 210));
        graphics.fillRoundRect(0, 0, size, size, radius, radius);
        graphics.setColor(plugin.isTerrorbirdBattleReady()
            ? new Color(231, 178, 83) : new Color(115, 120, 128));
        graphics.setStroke(new BasicStroke(Math.max(1f, size / 22f)));
        graphics.drawRoundRect(1, 1, size - 3, size - 3, radius, radius);

        Font oldFont = graphics.getFont();
        graphics.setFont(oldFont.deriveFont(Font.BOLD, Math.max(9f, size / 5f)));
        FontMetrics metrics = graphics.getFontMetrics();
        int lineHeight = metrics.getHeight();
        int baseline = (size - 2 * lineHeight) / 2 + metrics.getAscent();
        graphics.drawString("Battle", (size - metrics.stringWidth("Battle")) / 2, baseline);
        graphics.drawString("Ready", (size - metrics.stringWidth("Ready")) / 2,
            baseline + lineHeight);
        graphics.setFont(oldFont);
        return new Dimension(size, size);
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        if (isAvailable() && SwingUtilities.isLeftMouseButton(event)
            && getBounds().contains(event.getPoint()))
        {
            event.consume();
            clientThread.invokeLater(plugin::toggleTerrorbirdBattleReady);
        }
        return event;
    }

    @Override public MouseEvent mouseClicked(MouseEvent event) { return event; }
    @Override public MouseEvent mouseReleased(MouseEvent event) { return event; }
    @Override public MouseEvent mouseEntered(MouseEvent event) { return event; }
    @Override public MouseEvent mouseExited(MouseEvent event) { return event; }
    @Override public MouseEvent mouseDragged(MouseEvent event) { return event; }
    @Override public MouseEvent mouseMoved(MouseEvent event) { return event; }
}

package com.rapidursa.mounts;

public enum RidingPose
{
    STANDARD("Standard"),
    WIDE("Wide"),
    EXTRA_WIDE("Extra Wide"),
    CROSS_LEGGED("Cross-legged"),
    NO_SADDLE("No Saddle");

    private final String displayName;

    RidingPose(String displayName)
    {
        this.displayName = displayName;
    }

    @Override
    public String toString()
    {
        return displayName;
    }

    static RidingPose[] supportedFor(MountType mount)
    {
        switch (mount)
        {
            case BLACK_UNICORN:
                return new RidingPose[]{STANDARD, WIDE};
            case TERRORBIRD:
                return new RidingPose[]{STANDARD, WIDE};
            case LAVA_DRAGON:
                return new RidingPose[]{STANDARD, CROSS_LEGGED};
            case GRYPHON:
                return new RidingPose[]{STANDARD};
            case BATTLE_TURTLE:
                return new RidingPose[]{CROSS_LEGGED};
            case ARTIO:
                return new RidingPose[]{STANDARD, EXTRA_WIDE, NO_SADDLE};
            case ARAXXOR:
            case VORKATH:
            case BIG_WOLF:
            case CATABLEPON:
            case SHEEP:
                return new RidingPose[]{EXTRA_WIDE};
            case TZREK_ZUK:
                return new RidingPose[]{STANDARD, CROSS_LEGGED, EXTRA_WIDE};
            case FLYING_DRAGON:
                return new RidingPose[]{EXTRA_WIDE};
            default:
                return new RidingPose[]{STANDARD};
        }
    }

    static RidingPose defaultFor(MountType mount)
    {
        if (mount == MountType.BLACK_UNICORN)
        {
            return WIDE;
        }
        if (mount == MountType.ARTIO || mount == MountType.ARAXXOR || mount == MountType.VORKATH
            || mount == MountType.BIG_WOLF || mount == MountType.CATABLEPON
            || mount == MountType.SHEEP || mount == MountType.TZREK_ZUK
            || mount == MountType.FLYING_DRAGON)
        {
            return EXTRA_WIDE;
        }
        if (mount == MountType.BATTLE_TURTLE)
        {
            return CROSS_LEGGED;
        }
        return STANDARD;
    }

    static boolean supports(MountType mount, RidingPose pose)
    {
        if (pose == null)
        {
            return false;
        }
        for (RidingPose supported : supportedFor(mount))
        {
            if (supported == pose)
            {
                return true;
            }
        }
        return false;
    }

    boolean usesExtraWideAnimation()
    {
        return this == EXTRA_WIDE || this == NO_SADDLE;
    }
}

package com.rapidursa.mounts.appearance;

import java.util.Collections;
import java.util.Map;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * The spotanim ("graphic") catalogue parsed from the live game cache. A
 * spotanim is how the game shows teleport swirls, spell
 * impacts and the home teleport's rune circle: a model, the animation that
 * plays it once, scaling, rotation, recolours and lighting tweaks.
 *
 * <p>{@code Actor.getGraphic()} exposes the active id; the parsed definition
 * supplies the corresponding model and animation data.
 */
@Slf4j
@Singleton
public class SpotAnimRepository
{
	/** One spotanim definition. Field names mirror the dumper's. */
	public static class Entry
	{
		public int m;
		public int a;
		public Integer rx;
		public Integer ry;
		public Integer rot;
		public Integer am;
		public Integer co;
		public short[] cf;
		public short[] cr;
		public short[] tf;
		public short[] tr;

		public int modelId()
		{
			return m;
		}

		public int animationId()
		{
			return a;
		}

		public int resizeX()
		{
			return rx == null ? 128 : rx;
		}

		public int resizeY()
		{
			return ry == null ? 128 : ry;
		}

		public int rotation()
		{
			return rot == null ? 0 : rot;
		}

		public int ambient()
		{
			return am == null ? 0 : am;
		}

		public int contrast()
		{
			return co == null ? 0 : co;
		}
	}

	private Map<String, Entry> spotanims = Collections.emptyMap();

	@Getter
	private String status = "not loaded";

	/**
	 * Builds the catalogue from the client's own loaded cache. No-op
	 * while the cache indexes are not available yet; callers retry.
	 */
	public void loadFromClient(net.runelite.api.Client client)
	{
		Map<String, Entry> live = LiveCacheParser.parseSpotAnims(client);
		if (live.isEmpty())
		{
			return;
		}
		spotanims = live;
		status = spotanims.size() + " spotanims (live cache)";
		log.info("Loaded {} spotanims from live cache", spotanims.size());
	}

	/** The definition for a graphic id, or null if unknown or not loaded. */
	public Entry get(int graphicId)
	{
		return spotanims.get(Integer.toString(graphicId));
	}

	public boolean isLoaded()
	{
		return !spotanims.isEmpty();
	}
}

package com.rapidursa.mounts.appearance;

/**
 * The client's hardcoded body-colour tables, recovered empirically on 2026-08-02.
 *
 * <p>The game colours a player by plain find/replace over the merged model: each
 * body-colour slot has one source colour (hair has two - base and highlight are
 * authored separately, the highlight is never derived), replaced by the table
 * entry for the player's chosen index. The tables live in the client binary and
 * are not API-reachable, so they were read out with {@code ::follower harvest}:
 * every index of every slot was applied to the live composition client-side and
 * the resulting recolour extracted bit-exactly from the lit model.
 *
 * <p>Validation: the first 12 hair, 16 torso/legs, 6 boots and 8 skin entries
 * reproduce the classic-era tables value for value; the remainder are the modern
 * additions. Re-run the harvest after a game update that adds colours.
 */
public final class GamePalette
{
	/** Source colours the tables replace, one per body-colour slot. */
	public static final short HAIR_FIND = 6798;
	public static final short HAIR_HIGHLIGHT_FIND = (short) -10304;
	public static final short TORSO_FIND = 8741;
	public static final short LEGS_FIND = 25238;
	public static final short BOOTS_FIND = 4626;
	public static final short SKIN_FIND = 4550;

	public static final short[] HAIR = {
		6798, 107, 10283, 16, 4797, 7744, 5799, 4634, -31839, 22433,
		2983, -11343, 8, 5281, 10438, 3650, -27322, -21845, 200, 571,
		908, 21830, 28946, -15701, -14010, -22122, 937, 8130, -13422, 30385,
	};

	public static final short[] HAIR_HIGHLIGHT = {
		6554, 115, 10304, 28, 5702, 7756, 5681, 4510, -31835, 22437,
		2859, -11339, 16, 5157, 10446, 3658, -27314, -21965, 472, 580,
		784, 21966, 28950, -15697, -14002, -22116, 945, 8144, -13414, 30389,
	};

	public static final short[] TORSO = {
		8741, 12, -1506, -22374, 7735, 8404, 1701, -27106, 24094, 10153,
		-8915, 4783, 1341, 16578, -30533, 25239, 8, 5281, 10438, 3650,
		-27322, -21845, 200, 571, 908, 21830, 28946, -15701, -14010,
	};

	public static final short[] LEGS = {
		25238, 8742, 12, -1506, -22374, 7735, 8404, 1701, -27106, 24094,
		10153, -8915, 4783, 1341, 16578, -30533, 8, 5281, 10438, 3650,
		-27322, -21845, 200, 571, 908, 21830, 28946, -15701, -14010,
	};

	public static final short[] BOOTS = {
		4626, 11146, 6439, 12, 4758, 10270,
	};

	public static final short[] SKIN = {
		4550, 4537, 5681, 5673, 5790, 6806, 8076, 4574, 17050, 0,
		127, -31821, -17991,
	};

	private GamePalette()
	{
	}

	/** Table for one body-colour slot in {@code PlayerComposition#getColors()} order. */
	public static short[] table(int colorSlot)
	{
		switch (colorSlot)
		{
			case 0:
				return HAIR;
			case 1:
				return TORSO;
			case 2:
				return LEGS;
			case 3:
				return BOOTS;
			case 4:
				return SKIN;
			default:
				return null;
		}
	}

	/** Source colour for one body-colour slot; hair's highlight is handled separately. */
	public static short find(int colorSlot)
	{
		switch (colorSlot)
		{
			case 0:
				return HAIR_FIND;
			case 1:
				return TORSO_FIND;
			case 2:
				return LEGS_FIND;
			case 3:
				return BOOTS_FIND;
			case 4:
				return SKIN_FIND;
			default:
				return 0;
		}
	}
}

package com.rapidursa.mounts.appearance;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.kit.KitType;

/**
 * Holds item and body-kit model mappings parsed from the live game cache.
 *
 * <p>The RuneLite API's {@code ItemComposition} only exposes {@code getInventoryModel()};
 * the worn model ids ({@code maleModel0..2} / {@code femaleModel0..2}) and body kit models
 * live in the cache definitions. This class stores the parsed definitions so
 * {@link AppearanceComposer} can rebuild a player model from parts.
 */
@Slf4j
@Singleton
public class ModelRepository
{
	/** An item the follower can wear, for the outfit picker. */
	public static class WearableItem
	{
		public final int id;
		public final String name;

		WearableItem(int id, String name)
		{
			this.id = id;
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	public static class Entry
	{
		/** Item name; present in dumps produced by the current dumper. */
		public String n;
		/** Kits only: KitDefinition.bodyPartId, encoding both body part and gender. */
		public Integer bp;
		/** Vertical offsets the client applies to a worn model before merging. */
		public Integer mo;
		public Integer fo;

		/**
		 * Equipment slots this item occupies. wp1 is where it goes; wp2 and wp3 are
		 * further slots it HIDES - a platebody hides the arms kit, a full helm hides
		 * hair and jaw. Indices match KitType.
		 */
		public Integer wp1;
		public Integer wp2;
		public Integer wp3;

		public int offset(int gender)
		{
			Integer chosen = gender == 1 ? fo : mo;
			return chosen == null ? 0 : chosen;
		}
		/** Male worn model ids, -1 for unused. */
		public int[] m;
		/** Female worn model ids, -1 for unused. */
		public int[] f;
		/** Colours to find / replace with. */
		public short[] cf;
		public short[] cr;
		/** Textures to find / replace with. */
		public short[] tf;
		public short[] tr;

		public int[] models(int gender)
		{
			int[] chosen = gender == 1 ? f : m;
			if (chosen == null || chosen.length == 0)
			{
				chosen = gender == 1 ? m : f;
			}
			return chosen;
		}

		/**
		 * Chathead models: items carry male/female dialogue-head variants, kits
		 * carry KitDefinition.chatheadModels. These are the separate models real
		 * dialogs animate, with their own talk-animation skeletons.
		 */
		public int[] hm;
		public int[] hf;
		public int[] ch;

		/** The dialogue-head models for this entry, or null if it has none. */
		public int[] headModels(int gender)
		{
			if (ch != null)
			{
				return ch;
			}
			int[] chosen = gender == 1 ? hf : hm;
			if (chosen == null)
			{
				chosen = gender == 1 ? hm : hf;
			}
			return chosen;
		}
	}

	@Getter
	private volatile boolean loaded;

	@Getter
	private volatile String status = "not loaded";

	private volatile Map<String, Entry> items = Collections.emptyMap();
	private volatile Map<String, Entry> kits = Collections.emptyMap();

	/**
	 * Builds the catalogue from the client's own loaded cache.
	 * No-op while the cache indexes are not available yet; callers retry.
	 */
	public void loadFromClient(net.runelite.api.Client client)
	{
		Map<String, Entry> liveItems = LiveCacheParser.parseItems(client);
		if (liveItems.isEmpty())
		{
			return;
		}
		items = liveItems;
		kits = LiveCacheParser.parseKits(client);
		loaded = true;
		status = items.size() + " items, " + kits.size() + " kits (live cache)";
		log.info("Loaded model catalogue from live cache: {}", status);
	}

	public void unload()
	{
		items = Collections.emptyMap();
		kits = Collections.emptyMap();
		loaded = false;
		status = "not loaded";
	}

	public Entry item(int itemId)
	{
		return items.get(Integer.toString(itemId));
	}

	/** Name of a dumped item, or null if this dump predates name support. */
	public String itemName(int itemId)
	{
		Entry entry = item(itemId);
		return entry == null ? null : entry.n;
	}

	/**
	 * Every wearable item whose name matches {@code query}, sorted by name. The dump
	 * contains exactly the items that have worn models, so this is the complete set
	 * of things the follower can actually be dressed in.
	 */
	public List<WearableItem> search(String query, int limit)
	{
		String needle = query == null ? "" : query.trim().toLowerCase(java.util.Locale.ROOT);
		List<WearableItem> matches = new ArrayList<>();

		for (Map.Entry<String, Entry> entry : items.entrySet())
		{
			String name = entry.getValue().n;
			if (name == null || name.isEmpty() || "null".equals(name))
			{
				continue;
			}
			if (!needle.isEmpty() && !name.toLowerCase(java.util.Locale.ROOT).contains(needle))
			{
				continue;
			}

			try
			{
				matches.add(new WearableItem(Integer.parseInt(entry.getKey()), name));
			}
			catch (NumberFormatException ignored)
			{
				// Malformed key in the dump; skip it.
			}

			if (matches.size() >= limit * 4)
			{
				break;
			}
		}

		matches.sort((a, b) ->
		{
			// Exact and prefix matches first, then alphabetical.
			boolean ap = a.name.toLowerCase(java.util.Locale.ROOT).startsWith(needle);
			boolean bp = b.name.toLowerCase(java.util.Locale.ROOT).startsWith(needle);
			if (ap != bp)
			{
				return ap ? -1 : 1;
			}
			return a.name.compareToIgnoreCase(b.name);
		});

		return matches.size() > limit ? matches.subList(0, limit) : matches;
	}

	/**
	 * Body parts in bodyPartId order. The id is this index for a male kit, and this
	 * index + 7 for a female one - verified against the whole dump, which is
	 * symmetric across the two halves.
	 */
	private static final KitType[] BODY_PART_ORDER = {
		KitType.HAIR, KitType.JAW, KitType.TORSO, KitType.ARMS,
		KitType.HANDS, KitType.LEGS, KitType.BOOTS,
	};

	private static final int PARTS_PER_GENDER = BODY_PART_ORDER.length;

	/** @return the bodyPartId a kit must have to belong to this slot and gender. */
	public static int bodyPartId(KitType part, int gender)
	{
		for (int i = 0; i < BODY_PART_ORDER.length; i++)
		{
			if (BODY_PART_ORDER[i] == part)
			{
				return i + (gender == 1 ? PARTS_PER_GENDER : 0);
			}
		}
		return -1;
	}

	/**
	 * Kit ids the cache flags non-selectable - the styles character creation
	 * never offers. Read from the live cache; empty until that lands.
	 */
	private volatile java.util.Set<Integer> nonSelectableKits = Collections.emptySet();

	public void setNonSelectableKits(java.util.Set<Integer> ids)
	{
		nonSelectableKits = ids == null ? Collections.emptySet() : ids;
	}

	/**
	 * Every kit the picker should offer for one body part and gender, sorted
	 * by id. Two filters make this the list a player recognises rather than a
	 * raw cache listing:
	 *
	 * <ul>
	 *   <li>kits flagged non-selectable are dropped - those are the NPC-only
	 *   and unreleased styles character creation hides;</li>
	 *   <li>kits whose models and chatheads are byte-identical to an earlier
	 *   one are dropped - the cache holds several such pairs (33/35 hands,
	 *   43/44 boots, 141/142/152 female hair, ...) which rendered as
	 *   duplicate entries that looked and behaved identically.</li>
	 * </ul>
	 */
	public List<Integer> kitsFor(KitType part, int gender)
	{
		int wanted = bodyPartId(part, gender);
		List<Integer> ids = new ArrayList<>();
		if (wanted < 0)
		{
			return ids;
		}

		for (Map.Entry<String, Entry> entry : kits.entrySet())
		{
			Integer bodyPart = entry.getValue().bp;
			if (bodyPart == null || bodyPart != wanted)
			{
				continue;
			}
			try
			{
				int id = Integer.parseInt(entry.getKey());
				if (!nonSelectableKits.contains(id))
				{
					ids.add(id);
				}
			}
			catch (NumberFormatException ignored)
			{
				// Malformed key; skip.
			}
		}

		ids.sort(Integer::compareTo);

		List<Integer> distinct = new ArrayList<>(ids.size());
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (int id : ids)
		{
			if (seen.add(appearanceSignature(kits.get(Integer.toString(id)))))
			{
				distinct.add(id);
			}
		}
		return distinct;
	}

	/** What the kit actually looks like: identical signatures render identically. */
	private static String appearanceSignature(Entry entry)
	{
		if (entry == null)
		{
			return "null";
		}
		return java.util.Arrays.toString(entry.m)
			+ java.util.Arrays.toString(entry.ch)
			+ java.util.Arrays.toString(entry.cf)
			+ java.util.Arrays.toString(entry.cr)
			+ java.util.Arrays.toString(entry.tf)
			+ java.util.Arrays.toString(entry.tr);
	}

	/** True if the dump carries body-part metadata (older dumps do not). */
	public boolean hasKitParts()
	{
		for (Entry e : kits.values())
		{
			return e.bp != null;
		}
		return false;
	}

	/** Every wearable item id in the dump. */
	public List<Integer> allItemIds()
	{
		List<Integer> ids = new ArrayList<>(items.size());
		for (String key : items.keySet())
		{
			try
			{
				ids.add(Integer.parseInt(key));
			}
			catch (NumberFormatException ignored)
			{
				// Malformed key; skip.
			}
		}
		return ids;
	}

	public boolean hasNames()
	{
		for (Entry e : items.values())
		{
			return e.n != null;
		}
		return false;
	}

	public Entry kit(int kitId)
	{
		return kits.get(Integer.toString(kitId));
	}

	public boolean hasItem(int itemId)
	{
		return items.containsKey(Integer.toString(itemId));
	}
}

package com.rapidursa.mounts.appearance;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.kit.KitType;

/**
 * Rebuilds a player model from its parts, the same way the game does: load each
 * worn model and body kit model from the cache, apply that part's colour and
 * texture replacements, merge everything, then light it.
 *
 * <p>Must be called on the client thread.
 */
@Slf4j
@Singleton
public class AppearanceComposer
{
	/**
	 * Lighting applied to the composed model. Verified 2026-08-02 against the
	 * deobfuscated client: PlayerComposition builds the player with
	 * {@code toModel(64, 850, -30, -50, -30)}, matching these exactly.
	 */
	private static final int AMBIENT = 64;
	private static final int CONTRAST = 850;
	private static final int LIGHT_X = -30;
	private static final int LIGHT_Y = -50;
	private static final int LIGHT_Z = -30;

	/**
	 * Interface models are lit DIFFERENTLY from actors - verified in the client:
	 * widget models get {@code calculateNormals(64, 768, -50, -10, -50)}, a softer
	 * contrast and a front-left light, where actors get {@code (64, 850, -30,
	 * -50, -30)}. Lighting a chathead with the actor constants is what made it
	 * shade differently from a real dialog's head.
	 */
	private static final int WIDGET_CONTRAST = 768;
	private static final int WIDGET_LIGHT_X = -50;
	private static final int WIDGET_LIGHT_Y = -10;
	private static final int WIDGET_LIGHT_Z = -50;

	private final Client client;
	private final ModelRepository repository;

	/**
	 * Exact body recolours captured from the live client by {@code ::follower
	 * palette}: source colour -> replacement, both packed HSL, applied to the merged
	 * model exactly the way PlayerComposition does. While any pairs are present they
	 * take the place of the palette-index recolouring in {@link #applyBodyColors}.
	 */
	private final java.util.Map<Short, Short> exactPairs = new java.util.LinkedHashMap<>();
	private Short liveSkinColor;

	public void setLiveSkinColor(Short color)
	{
		liveSkinColor = color;
	}

	public void setExactPairs(java.util.Map<Short, Short> pairs)
	{
		exactPairs.clear();
		if (pairs != null)
		{
			exactPairs.putAll(pairs);
		}
	}

	public java.util.Map<Short, Short> getExactPairs()
	{
		return new java.util.LinkedHashMap<>(exactPairs);
	}

	/**
	 * A vertex nudge for one item, applied before the merge.
	 *
	 * <p>A worn model's place on the body is baked into its vertices, authored
	 * for how the ORIGINAL context holds it - a god book sits where a wielded
	 * god book sits, not where the reading animation's hands meet. There is no
	 * transform to read back and correct; the only sensor for "it looks wrong"
	 * is an eye, so the values here arrive by nudging in game until it looks
	 * right ({@code ::follower propoffset}).
	 *
	 * <p>Model space: y is vertical and NEGATIVE is up; x and z are the
	 * horizontal plane, relative to the model's facing. A tile is 128 units,
	 * so hand-scale corrections are single digits to low tens.
	 */
	private int adjustItemId = -1;
	private float adjustX;
	private float adjustY;
	private float adjustZ;
	private float capeY;
	private float capeZ;

	public void setItemAdjustment(int itemId, float x, float y, float z)
	{
		adjustItemId = itemId;
		adjustX = x;
		adjustY = y;
		adjustZ = z;
	}

	public String describeItemAdjustment()
	{
		return adjustItemId < 0 ? "none"
			: "item " + adjustItemId + " by x=" + adjustX
				+ " y=" + adjustY + " z=" + adjustZ;
	}

	/**
	 * Moves only the cosmetic rider's cape before the appearance parts are merged.
	 * Model-space Y is inverted, so a positive UI height becomes a negative Y
	 * translation. Z follows the player's forward/back axis.
	 */
	public void setCapeAdjustment(float height, float backward)
	{
		capeY = -height;
		capeZ = backward;
	}

	@Inject
	public AppearanceComposer(Client client, ModelRepository repository)
	{
		this.client = client;
		this.repository = repository;
	}

	/**
	 * @return a composed model, or null if the dump is missing or has no data for
	 * any of the outfit's slots (caller should fall back to capture).
	 */
	public Model compose(Outfit outfit)
	{
		return composeSelected(outfit, java.util.EnumSet.allOf(KitType.class));
	}

	/** Composes whole equipment slots so separately animated parts stay intact. */
	public Model composeSelected(Outfit outfit, java.util.Set<KitType> selected)
	{
		if (!repository.isLoaded())
		{
			return null;
		}

		Outfit resolved = outfit.withDefaultBody();
		List<ModelData> parts = new ArrayList<>();
		List<String> missing = new ArrayList<>();

		// Body kits hidden by the gear on top of them.
		java.util.Set<KitType> hidden = hiddenSlots(resolved);

		for (KitType slot : KitType.values())
		{
			if (!selected.contains(slot))
			{
				continue;
			}
			int raw = resolved.getRaw(slot);
			if (raw == 0)
			{
				continue;
			}

			// Skip whatever the gear covers: the arms under a platebody, the hair and
			// beard under a full helm, the shield behind a two-hander. Drawing both is
			// what pushes one through the other.
			if (hidden.contains(slot))
			{
				continue;
			}

			boolean item = raw >= Outfit.ITEM_OFFSET;
			int id = item ? raw - Outfit.ITEM_OFFSET : raw - Outfit.KIT_OFFSET;
			ModelRepository.Entry entry = item ? repository.item(id) : repository.kit(id);

			if (entry == null)
			{
				missing.add(slot.name() + " " + (item ? "item " : "kit ") + id);
				continue;
			}

			// Parts stay in their authored source colours; body colouring happens
			// post-merge via the palette tables, exactly as the client does it.
			int before = parts.size();
			addPart(parts, entry, resolved.getGender());

			// The nudge, applied to every model this item contributed. After
			// the colour clones and before the merge: a merged model shares
			// nothing back, but the loaded parts share arrays with every other
			// caller of loadModelData, hence cloneVertices first.
			if (item && id == adjustItemId
				&& (adjustX != 0 || adjustY != 0 || adjustZ != 0))
			{
				for (int i = before; i < parts.size(); i++)
				{
					ModelData nudged = parts.get(i).cloneVertices();
					translate(nudged, adjustX, adjustY, adjustZ);
					parts.set(i, nudged);
				}
			}

			if (slot == KitType.CAPE && (capeY != 0 || capeZ != 0))
			{
				for (int i = before; i < parts.size(); i++)
				{
					ModelData nudged = parts.get(i).cloneVertices();
					translate(nudged, 0, capeY, capeZ);
					parts.set(i, nudged);
				}
			}
		}

		if (!missing.isEmpty())
		{
			log.debug("Model dump has no data for: {}", String.join(", ", missing));
		}

		if (parts.isEmpty())
		{
			return null;
		}

		ModelData merged = client.mergeModels(parts.toArray(new ModelData[0]));
		if (merged == null)
		{
			return null;
		}

		if (!exactPairs.isEmpty())
		{
			// The client's own mechanism: plain find/replace on the merged model.
			merged = merged.cloneColors();
			for (java.util.Map.Entry<Short, Short> pair : exactPairs.entrySet())
			{
				merged.recolor(pair.getKey(), pair.getValue());
			}
		}
		else
		{
			merged = applyBodyColors(merged, resolved.getColors());
		}

		// The ground clearance offset is applied when positioning, not baked into the
		// vertices - it belongs in world space alongside the terrain height, and this
		// keeps the composed model reusable across positions.
		return merged.light(AMBIENT, CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z);
	}

	/**
	 * Composes the outfit's dialogue chathead: the game's own separate head models
	 * (helm head variant, hair chathead, jaw chathead), coloured through the same
	 * palette as the body and lit the same way. These models carry the skeletons
	 * that talk animations are authored for, which the body model does not.
	 *
	 * @return the lit chathead, or null when the dump has no head data for this
	 * outfit (caller should fall back to cropping the body model)
	 */
	public Model composeChathead(Outfit outfit)
	{
		if (!repository.isLoaded() || outfit == null)
		{
			return null;
		}

		Outfit resolved = outfit.withDefaultBody();
		java.util.Set<KitType> hidden = hiddenSlots(resolved);
		List<ModelData> parts = new ArrayList<>();

		// Same wearPos rules as the body: a full helm hides hair and jaw in the
		// dialogue head too; a med helm hides hair but keeps the beard.
		if (resolved.isItem(KitType.HEAD))
		{
			addHeadPart(parts, repository.item(resolved.itemId(KitType.HEAD)), resolved.getGender());
		}
		if (!hidden.contains(KitType.HAIR) && resolved.isKit(KitType.HAIR))
		{
			addHeadPart(parts, repository.kit(resolved.kitId(KitType.HAIR)), resolved.getGender());
		}
		if (!hidden.contains(KitType.JAW) && resolved.isKit(KitType.JAW))
		{
			addHeadPart(parts, repository.kit(resolved.kitId(KitType.JAW)), resolved.getGender());
		}

		if (parts.isEmpty())
		{
			return null;
		}

		ModelData merged = client.mergeModels(parts.toArray(new ModelData[0]));
		if (merged == null)
		{
			return null;
		}

		if (!exactPairs.isEmpty())
		{
			merged = merged.cloneColors();
			for (java.util.Map.Entry<Short, Short> pair : exactPairs.entrySet())
			{
				merged.recolor(pair.getKey(), pair.getValue());
			}
		}
		else
		{
			merged = applyBodyColors(merged, resolved.getColors());
		}

		return merged.light(AMBIENT, WIDGET_CONTRAST,
			WIDGET_LIGHT_X, WIDGET_LIGHT_Y, WIDGET_LIGHT_Z);
	}

	/** Loads an entry's dialogue-head models with its authored recolours applied. */
	private void addHeadPart(List<ModelData> parts, ModelRepository.Entry entry, int gender)
	{
		int[] modelIds = entry == null ? null : entry.headModels(gender);
		if (modelIds == null)
		{
			return;
		}

		for (int modelId : modelIds)
		{
			if (modelId < 0)
			{
				continue;
			}

			ModelData data = client.loadModelData(modelId);
			if (data == null)
			{
				continue;
			}

			if (hasPairs(entry.cf, entry.cr))
			{
				data = data.cloneColors();
				for (int i = 0; i < entry.cf.length && i < entry.cr.length; i++)
				{
					data.recolor(entry.cf[i], entry.cr[i]);
				}
			}
			if (hasPairs(entry.tf, entry.tr))
			{
				data = data.cloneTextures();
				for (int i = 0; i < entry.tf.length && i < entry.tr.length; i++)
				{
					data.retexture(entry.tf[i], entry.tr[i]);
				}
			}

			parts.add(data);
		}
	}

	/** ModelData has no translate; the mesh exposes its vertex arrays instead. */
	private static void translate(ModelData data, float dx, float dy, float dz)
	{
		float[] xs = data.getVerticesX();
		float[] ys = data.getVerticesY();
		float[] zs = data.getVerticesZ();
		for (int v = 0; v < data.getVerticesCount(); v++)
		{
			xs[v] += dx;
			ys[v] += dy;
			zs[v] += dz;
		}
	}

	/**
	 * Body-kit slots covered by the equipped gear, taken from each item's wearPos data.
	 *
	 * <p>This is how the game itself decides what to draw. An item declares the slot it
	 * occupies plus up to two more that it <em>hides</em>: a platebody hides the arms
	 * kit, a full helm hides both hair and jaw. Around 2,200 of the 6,300 wearable items
	 * hide something.
	 *
	 * <p>This replaces a single hardcoded rule - "a torso item hides the arms" - which
	 * covered one case out of many and left helmets rendering hair straight through
	 * themselves.
	 */
	java.util.Set<KitType> hiddenSlots(Outfit outfit)
	{
		java.util.Set<KitType> hidden = java.util.EnumSet.noneOf(KitType.class);
		KitType[] slots = KitType.values();

		for (KitType slot : slots)
		{
			if (!outfit.isItem(slot))
			{
				continue;
			}

			ModelRepository.Entry entry = repository.item(outfit.itemId(slot));
			if (entry == null)
			{
				continue;
			}

			for (Integer covered : new Integer[]{entry.wp2, entry.wp3})
			{
				if (covered != null && covered >= 0 && covered < slots.length)
				{
					hidden.add(slots[covered]);
				}
			}
		}

		return hidden;
	}

	/**
	 * Extracts the client's body-colour palette by differencing.
	 *
	 * <p>The client colours a player by two plain find/replace passes per colour slot
	 * over the merged model, using palette tables hardcoded in the client and not
	 * reachable from a plugin. But the tables can be read out empirically: compose
	 * this outfit with NO body recolouring, then diff unlit face colours against the
	 * client's own build of the same outfit, where the palette has already been
	 * applied. Faces are compared positionally - both builds merge the same parts in
	 * the same slot order, proven by exact face-count and priority matches - so every
	 * differing face yields one exact (find -> replace) pair from Jagex's tables.
	 *
	 * <p>This replaces guessing at hair colours entirely: the pair for the player's
	 * current hair IS the table entry, highlight included, since base and highlight
	 * are separate source colours with separate replacements.
	 */
	public List<String> comparePalette(Outfit outfit, Model clientModel,
		java.util.Map<Short, Short> collect)
	{
		return comparePalette(outfit, clientModel, collect, false);
	}

	/** Read only the skin replacement from another plugin's live player model. */
	public Short detectLiveSkinColor(Outfit outfit, Model clientModel)
	{
		java.util.Map<Short, Short> matches = new java.util.HashMap<>();
		comparePalette(outfit, clientModel, matches, true);
		return matches.get(GamePalette.SKIN_FIND);
	}

	private List<String> comparePalette(Outfit outfit, Model clientModel,
		java.util.Map<Short, Short> collect, boolean skinOnly)
	{
		List<String> out = new ArrayList<>();
		if (!repository.isLoaded() || clientModel == null)
		{
			out.add("Need the model dump and a visible player model.");
			return out;
		}

		Outfit resolved = outfit.withDefaultBody();
		java.util.Set<KitType> hidden = hiddenSlots(resolved);

		List<ModelData> parts = new ArrayList<>();
		List<KitType> partSlots = new ArrayList<>();

		for (KitType slot : KitType.values())
		{
			int raw = resolved.getRaw(slot);
			if (raw == 0 || hidden.contains(slot))
			{
				continue;
			}

			boolean item = raw >= Outfit.ITEM_OFFSET;
			int id = item ? raw - Outfit.ITEM_OFFSET : raw - Outfit.KIT_OFFSET;
			ModelRepository.Entry entry = item ? repository.item(id) : repository.kit(id);
			if (entry == null)
			{
				continue;
			}

			int before = parts.size();
			addPart(parts, entry, resolved.getGender());
			while (partSlots.size() < parts.size())
			{
				partSlots.add(slot);
			}
			if (parts.size() == before)
			{
				out.add(slot + ": no models loaded, attribution may shift");
			}
		}

		ModelData merged = client.mergeModels(parts.toArray(new ModelData[0]));
		if (merged == null)
		{
			out.add("Merge failed.");
			return out;
		}

		// Live player models carry no unlit colours (getUnlitFaceColors() is null on
		// that path), so the comparison runs on LIT colours. Lighting rewrites only
		// the low 7 luminance bits of a packed colour; hue and saturation pass
		// through, so the client's lit faces reveal the replacement's hue+sat
		// directly. The luminance is recovered by brute force below.
		short[] unlit = merged.getFaceColors();
		Model mineLit = merged.shallowCopy().cloneColors()
			.light(AMBIENT, CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z);
		if (unlit == null || mineLit == null)
		{
			out.add("Could not light the composed model.");
			return out;
		}

		int[] mc1 = mineLit.getFaceColors1();
		int[] cc1 = clientModel.getFaceColors1();
		int[] mc2 = mineLit.getFaceColors2();
		int[] cc2 = clientModel.getFaceColors2();
		int[] mc3 = mineLit.getFaceColors3();
		int[] cc3 = clientModel.getFaceColors3();
		if (mc1 == null || cc1 == null || mc1.length != cc1.length)
		{
			out.add("Lit face arrays unavailable or mismatched ("
				+ (mc1 == null ? "-" : mc1.length) + " vs "
				+ (cc1 == null ? "-" : cc1.length) + "), aborting.");
			return out;
		}

		// Face index -> contributing slot, from each part's face count in merge order.
		int[] partEnds = new int[parts.size()];
		int running = 0;
		for (int i = 0; i < parts.size(); i++)
		{
			short[] colors = parts.get(i).getFaceColors();
			running += colors == null ? 0 : colors.length;
			partEnds[i] = running;
		}

		// Group differing faces by their source colour in my un-recoloured build.
		java.util.Map<Short, List<Integer>> groups = new java.util.LinkedHashMap<>();
		java.util.Map<Short, java.util.Set<KitType>> where = new java.util.HashMap<>();

		int part = 0;
		for (int face = 0; face < mc1.length; face++)
		{
			while (part < partEnds.length - 1 && face >= partEnds[part])
			{
				part++;
			}
			if (mc1[face] == cc1[face] && mc2[face] == cc2[face] && mc3[face] == cc3[face])
			{
				continue;
			}

			groups.computeIfAbsent(unlit[face], k -> new ArrayList<>()).add(face);
			where.computeIfAbsent(unlit[face], k -> java.util.EnumSet.noneOf(KitType.class))
				.add(partSlots.get(part));
		}

		if (groups.isEmpty())
		{
			out.add("All " + mc1.length + " faces already match - the client applied "
				+ "no body recolouring to this outfit.");
			return out;
		}

		out.add(groups.size() + " recoloured source colours over " + mc1.length + " faces:");
		for (java.util.Map.Entry<Short, List<Integer>> group : groups.entrySet())
		{
			short find = group.getKey();
			if (skinOnly && find != GamePalette.SKIN_FIND)
			{
				continue;
			}
			List<Integer> faces = group.getValue();

			// Any non-hidden face's lit colour carries the replacement's hue+sat.
			int hueSat = -1;
			for (int face : faces)
			{
				if (cc3[face] != -2)
				{
					hueSat = cc1[face] & 0xFF80;
					break;
				}
			}
			if (hueSat < 0)
			{
				out.add(String.format("%s: %s x%d - every face hidden, cannot recover",
					where.get(find), describeHsl(find), faces.size()));
				continue;
			}

			// Recover luminance: relight with each candidate and keep those whose lit
			// output matches the client's on every face in the group.
			List<Integer> lums = new ArrayList<>();
			for (int lum = 0; lum < 128; lum++)
			{
				short candidate = (short) (hueSat | lum);
				ModelData work = merged.shallowCopy().cloneColors();
				work.recolor(find, candidate);
				Model lit = work.light(AMBIENT, CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z);
				if (lit == null)
				{
					continue;
				}

				int[] wc1 = lit.getFaceColors1();
				int[] wc2 = lit.getFaceColors2();
				int[] wc3 = lit.getFaceColors3();
				boolean all = true;
				for (int face : faces)
				{
					if (wc1[face] != cc1[face] || wc2[face] != cc2[face] || wc3[face] != cc3[face])
					{
						all = false;
						break;
					}
				}
				if (all)
				{
					lums.add(lum);
				}
			}

			if (lums.isEmpty())
			{
				out.add(String.format("%s: %s x%d -> hue/sat %d but NO luminance "
						+ "reproduces the client - alignment or lighting is off",
					where.get(find), describeHsl(find), faces.size(), hueSat >> 7));
				continue;
			}

			short replacement = (short) (hueSat | lums.get(0));
			if (collect != null)
			{
				collect.put(find, replacement);
			}
			out.add(String.format("%s: %s -> %s x%d  (raw %d -> %d)%s",
				where.get(find), describeHsl(find), describeHsl(replacement),
				faces.size(), find, replacement,
				lums.size() > 1 ? "  [" + lums.size() + " luminances fit: " + lums + "]" : ""));
		}
		return out;
	}

	private static String describeHsl(short packed)
	{
		return String.format("h%02d s%d l%03d",
			HslColor.hue(packed), HslColor.saturation(packed), HslColor.luminance(packed));
	}

	/** Reports which slots the current gear covers, and which item covers each. */
	public List<String> describeHidden(Outfit outfit)
	{
		Outfit resolved = outfit.withDefaultBody();
		List<String> lines = new ArrayList<>();
		KitType[] slots = KitType.values();

		for (KitType slot : slots)
		{
			if (!resolved.isItem(slot))
			{
				continue;
			}

			int itemId = resolved.itemId(slot);
			ModelRepository.Entry entry = repository.item(itemId);
			if (entry == null)
			{
				lines.add(slot + ": item " + itemId + " not in dump");
				continue;
			}

			List<String> covers = new ArrayList<>();
			for (Integer covered : new Integer[]{entry.wp2, entry.wp3})
			{
				if (covered != null && covered >= 0 && covered < slots.length)
				{
					covers.add(slots[covered].name().toLowerCase(java.util.Locale.ROOT));
				}
			}

			lines.add(slot.name().toLowerCase(java.util.Locale.ROOT) + ": "
				+ (entry.n == null ? "item " + itemId : entry.n)
				+ (covers.isEmpty() ? " hides nothing" : " hides " + String.join(" + ", covers)));
		}

		if (lines.isEmpty())
		{
			lines.add("No gear equipped, so nothing is hidden.");
		}
		return lines;
	}

	private void addPart(List<ModelData> parts, ModelRepository.Entry entry, int gender)
	{
		int[] modelIds = entry.models(gender);
		if (modelIds == null)
		{
			return;
		}

		for (int modelId : modelIds)
		{
			if (modelId < 0)
			{
				continue;
			}

			ModelData data = client.loadModelData(modelId);
			if (data == null)
			{
				log.debug("Model {} not in cache", modelId);
				continue;
			}

			// loadModelData shares arrays between callers; clone before mutating.
			if (hasPairs(entry.cf, entry.cr))
			{
				data = data.cloneColors();
				for (int i = 0; i < entry.cf.length && i < entry.cr.length; i++)
				{
					data.recolor(entry.cf[i], entry.cr[i]);
				}
			}

			if (hasPairs(entry.tf, entry.tr))
			{
				data = data.cloneTextures();
				for (int i = 0; i < entry.tf.length && i < entry.tr.length; i++)
				{
					data.retexture(entry.tf[i], entry.tr[i]);
				}
			}

			// Each worn model carries a vertical offset that positions it against the
			// body. Merging without it leaves every piece at its raw origin, so
			// neighbouring pieces sit slightly wrong and clip into one another.
			int offset = entry.offset(gender);
			if (offset != 0)
			{
				data = data.cloneVertices();
				data.translate(0, offset, 0);
			}

			parts.add(data);
		}
	}

	/** Applies the five body-colour indices through the game's own palette tables. */
	private ModelData applyBodyColors(ModelData merged, int[] colorIndices)
	{
		if (colorIndices == null)
		{
			return merged;
		}

		merged = merged.cloneColors();
		for (int slot = 0; slot < colorIndices.length && slot < 5; slot++)
		{
			short[] table = GamePalette.table(slot);
			int index = colorIndices[slot];
			if (table == null || index < 0
				|| (index >= table.length && !(slot == 4 && liveSkinColor != null)))
			{
				continue;
			}

			merged.recolor(GamePalette.find(slot),
				slot == 4 && liveSkinColor != null ? liveSkinColor : table[index]);
			if (slot == 0 && index < GamePalette.HAIR_HIGHLIGHT.length)
			{
				// The highlight is its own authored colour with its own table entry,
				// never derived from the base - deriving it is what kept hair
				// almost-but-not-quite right for months.
				merged.recolor(GamePalette.HAIR_HIGHLIGHT_FIND, GamePalette.HAIR_HIGHLIGHT[index]);
			}
		}

		return merged;
	}

	private static boolean hasPairs(short[] find, short[] replace)
	{
		return find != null && replace != null && find.length > 0 && replace.length > 0;
	}
}

package com.rapidursa.mounts.appearance;

import java.awt.Color;

/**
 * Conversions for the game's packed colour format.
 *
 * <p>Model face colours are 16-bit HSL: hue in bits 10-15, saturation in bits 7-9,
 * luminance in bits 0-6. Lighting rewrites only the luminance bits, which is why
 * hue and saturation read off a lit model are the authored values.
 */
public final class HslColor
{
	private HslColor()
	{
	}

	public static int hue(short packed)
	{
		return (packed >> 10) & 0x3F;
	}

	public static int saturation(short packed)
	{
		return (packed >> 7) & 0x07;
	}

	public static int luminance(short packed)
	{
		return packed & 0x7F;
	}

	/**
	 * Approximates a packed game colour as RGB, for showing swatches in the panel.
	 * The game's own conversion table is internal to the client, so this is a plain
	 * HSL conversion over the same ranges - close enough to pick a colour by eye.
	 * The stored value is always the packed colour itself, never this RGB.
	 */
	public static int toRgb(short packed)
	{
		float h = hue(packed) / 63f;
		float s = saturation(packed) / 7f;
		float l = luminance(packed) / 127f;

		// HSL to RGB via HSB, which java.awt provides directly.
		float brightness = l + s * Math.min(l, 1f - l);
		float saturationHsb = brightness == 0f ? 0f : 2f * (1f - l / brightness);
		return Color.HSBtoRGB(h, Math.max(0f, Math.min(1f, saturationHsb)),
			Math.max(0f, Math.min(1f, brightness))) & 0xFFFFFF;
	}
}

package com.rapidursa.mounts.appearance;

import java.util.LinkedHashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;

/**
 * Parses item, kit and spotanim definitions straight out of the client's own
 * loaded cache ({@link Client#getIndexConfig()}), so the plugin needs no
 * offline dumps: Hub users get the full outfit catalogue and graphic
 * repository the moment the client is running.
 *
 * <p>The opcode logic is a faithful port of runelite-cache's ItemLoader,
 * KitLoader and SpotAnimLoader, transcribed from the library's bytecode and
 * validated in game by diffing every entry against the offline dumper's
 * output ({@code ::follower cachecheck}). Output shapes mirror the dump files
 * exactly, defaults included, so the repositories cannot tell the difference.
 *
 * <p>Every definition parses independently: a malformed or future-format
 * entry is skipped with a note rather than failing the whole catalogue.
 */
@Slf4j
public final class LiveCacheParser
{
	/** Config-index archive ids (net.runelite.cache.ConfigType). */
	private static final int CONFIG_IDENTKIT = 3;
	private static final int CONFIG_ITEM = 10;
	private static final int CONFIG_SEQUENCE = 12;
	private static final int CONFIG_SPOTANIM = 13;

	private LiveCacheParser()
	{
	}

	/**
	 * The id of every animation the cache holds.
	 *
	 * <p>Only the archive's file list is read, never the definitions: an id is
	 * either in there or it is not, which is the whole question a validity
	 * check asks. Used by {@code ::follower stanceaudit} to prove that no
	 * stance names an animation that does not exist.
	 */
	public static java.util.Set<Integer> sequenceIds(Client client)
	{
		IndexDataBase configs = client.getIndexConfig();
		java.util.Set<Integer> ids = new java.util.HashSet<>();
		if (configs == null)
		{
			return ids;
		}
		for (int id : configs.getFileIds(CONFIG_SEQUENCE))
		{
			ids.add(id);
		}
		return ids;
	}

	/** Wearable items keyed by id, matching equipment-models.json's items map. */
	public static Map<String, ModelRepository.Entry> parseItems(Client client)
	{
		IndexDataBase configs = client.getIndexConfig();
		Map<String, ModelRepository.Entry> items = new LinkedHashMap<>();
		if (configs == null)
		{
			return items;
		}
		int failures = 0;
		for (int id : configs.getFileIds(CONFIG_ITEM))
		{
			byte[] data = configs.loadData(CONFIG_ITEM, id);
			if (data == null)
			{
				continue;
			}
			try
			{
				ModelRepository.Entry entry = decodeItem(data);
				if (entry != null)
				{
					items.put(Integer.toString(id), entry);
				}
			}
			catch (RuntimeException e)
			{
				if (failures++ == 0)
				{
					log.warn("Item {} failed to parse (further failures counted silently)", id, e);
				}
			}
		}
		if (failures > 0)
		{
			log.warn("{} item definitions failed to parse", failures);
		}
		return items;
	}

	/** Body kits keyed by id, matching equipment-models.json's kits map. */
	public static Map<String, ModelRepository.Entry> parseKits(Client client)
	{
		return parseKits(client, null);
	}

	/**
	 * @param nonSelectableOut when non-null, receives the ids of kits flagged
	 * non-selectable - the styles character creation does not offer, which is
	 * how the NPC-only and unreleased extras are told apart from real player
	 * styles. Collected on the side so {@link ModelRepository.Entry} keeps the
	 * dump file's exact shape and {@code ::follower cachecheck} stays honest.
	 */
	public static Map<String, ModelRepository.Entry> parseKits(Client client,
		java.util.Set<Integer> nonSelectableOut)
	{
		IndexDataBase configs = client.getIndexConfig();
		Map<String, ModelRepository.Entry> kits = new LinkedHashMap<>();
		if (configs == null)
		{
			return kits;
		}
		for (int id : configs.getFileIds(CONFIG_IDENTKIT))
		{
			byte[] data = configs.loadData(CONFIG_IDENTKIT, id);
			if (data == null)
			{
				continue;
			}
			try
			{
				boolean[] nonSelectable = new boolean[1];
				ModelRepository.Entry entry = decodeKit(data, nonSelectable);
				if (entry != null)
				{
					kits.put(Integer.toString(id), entry);
					if (nonSelectable[0] && nonSelectableOut != null)
					{
						nonSelectableOut.add(id);
					}
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Kit {} failed to parse", id, e);
			}
		}
		return kits;
	}

	/** Spotanims keyed by id, matching spotanims.json. */
	public static Map<String, SpotAnimRepository.Entry> parseSpotAnims(Client client)
	{
		IndexDataBase configs = client.getIndexConfig();
		Map<String, SpotAnimRepository.Entry> spotAnims = new LinkedHashMap<>();
		if (configs == null)
		{
			return spotAnims;
		}
		int failures = 0;
		for (int id : configs.getFileIds(CONFIG_SPOTANIM))
		{
			byte[] data = configs.loadData(CONFIG_SPOTANIM, id);
			if (data == null)
			{
				continue;
			}
			try
			{
				SpotAnimRepository.Entry entry = decodeSpotAnim(data);
				if (entry != null)
				{
					spotAnims.put(Integer.toString(id), entry);
				}
			}
			catch (RuntimeException e)
			{
				if (failures++ == 0)
				{
					log.warn("Spotanim {} failed to parse: {}", id, e.getMessage());
				}
			}
		}
		if (failures > 0)
		{
			log.warn("{} spotanim definitions failed to parse", failures);
		}
		return spotAnims;
	}

	// ------------------------------------------------------------------ items

	/**
	 * ItemLoader's opcode walk. Only the fields the follower needs are kept,
	 * but EVERY opcode must be consumed at its exact width or the stream
	 * desynchronises and the rest of the definition parses as garbage.
	 */
	static ModelRepository.Entry decodeItem(byte[] data)
	{
		Buffer in = new Buffer(data);
		// The cache's convention for an unnamed item is the literal string
		// "null" (the definition's constructor default), and the dumper
		// preserved it - so the live parse must too.
		String name = "null";
		int maleModel0 = -1;
		int maleModel1 = -1;
		int maleModel2 = -1;
		int femaleModel0 = -1;
		int femaleModel1 = -1;
		int femaleModel2 = -1;
		int maleOffset = 0;
		int femaleOffset = 0;
		int maleHead = -1;
		int maleHead2 = -1;
		int femaleHead = -1;
		int femaleHead2 = -1;
		int wearPos1 = -1;
		int wearPos2 = -1;
		int wearPos3 = -1;
		short[] colorFind = null;
		short[] colorReplace = null;
		short[] textureFind = null;
		short[] textureReplace = null;

		for (int opcode = in.readUnsignedByte(); opcode != 0; opcode = in.readUnsignedByte())
		{
			switch (opcode)
			{
				case 1:
					in.readUnsignedShort(); // inventory model
					break;
				case 2:
					name = in.readString();
					break;
				case 3:
				case 9:
					in.readString(); // examine / unknown1
					break;
				case 4:
				case 5:
				case 6:
				case 7:
				case 8:
					in.readUnsignedShort(); // 2d zoom/rotation/offsets
					break;
				case 11:
				case 15:
				case 16:
				case 65:
				case 160:
					break; // flag opcodes carry no payload
				case 12:
					in.readInt(); // cost
					break;
				case 13:
					wearPos1 = in.readByte();
					break;
				case 14:
					wearPos2 = in.readByte();
					break;
				case 23:
					maleModel0 = in.readUnsignedShort();
					maleOffset = in.readUnsignedByte();
					break;
				case 24:
					maleModel1 = in.readUnsignedShort();
					break;
				case 25:
					femaleModel0 = in.readUnsignedShort();
					femaleOffset = in.readUnsignedByte();
					break;
				case 26:
					femaleModel1 = in.readUnsignedShort();
					break;
				case 27:
					wearPos3 = in.readByte();
					break;
				case 30:
				case 31:
				case 32:
				case 33:
				case 34:
				case 35:
				case 36:
				case 37:
				case 38:
				case 39:
					in.readString(); // ground / interface actions
					break;
				case 40:
				{
					int count = in.readUnsignedByte();
					colorFind = new short[count];
					colorReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						colorFind[i] = (short) in.readUnsignedShort();
						colorReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 41:
				{
					int count = in.readUnsignedByte();
					textureFind = new short[count];
					textureReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						textureFind[i] = (short) in.readUnsignedShort();
						textureReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 42:
					in.readByte(); // shift-click drop index
					break;
				case 43:
					// Menu subops: group byte, then (index byte, string) pairs
					// terminated by a zero index byte.
					in.readUnsignedByte();
					while (in.readUnsignedByte() != 0)
					{
						in.readString();
					}
					break;
				case 44:
					in.readInt(); // large inventory model
					break;
				case 45:
					maleModel0 = in.readInt();
					maleOffset = in.readUnsignedByte();
					break;
				case 46:
					maleModel1 = in.readInt();
					break;
				case 47:
					maleModel2 = in.readInt();
					break;
				case 48:
					femaleModel0 = in.readInt();
					femaleOffset = in.readUnsignedByte();
					break;
				case 49:
					femaleModel1 = in.readInt();
					break;
				case 50:
					femaleModel2 = in.readInt();
					break;
				case 51:
					maleHead = in.readInt();
					break;
				case 52:
					maleHead2 = in.readInt();
					break;
				case 53:
					femaleHead = in.readInt();
					break;
				case 54:
					femaleHead2 = in.readInt();
					break;
				case 75:
					in.readShort(); // weight
					break;
				case 78:
					maleModel2 = in.readUnsignedShort();
					break;
				case 79:
					femaleModel2 = in.readUnsignedShort();
					break;
				case 90:
					maleHead = in.readUnsignedShort();
					break;
				case 91:
					femaleHead = in.readUnsignedShort();
					break;
				case 92:
					maleHead2 = in.readUnsignedShort();
					break;
				case 93:
					femaleHead2 = in.readUnsignedShort();
					break;
				case 94:
				case 95:
				case 97:
				case 98:
				case 110:
				case 111:
				case 112:
				case 139:
				case 140:
				case 148:
				case 149:
					in.readUnsignedShort(); // category/noted/resize/links
					break;
				case 100:
				case 101:
				case 102:
				case 103:
				case 104:
				case 105:
				case 106:
				case 107:
				case 108:
				case 109:
					in.readUnsignedShort(); // stack count variant
					in.readUnsignedShort();
					break;
				case 113:
				case 114:
					in.readByte(); // ambient / contrast
					break;
				case 115:
					in.readUnsignedByte(); // team
					break;
				case 200:
					// EntityOpsLoader.decodeSubOp: byte, byte, string.
					in.readUnsignedByte();
					in.readUnsignedByte();
					in.readString();
					break;
				case 201:
					// decodeConditionalOp: byte, short, short, int, int, string.
					in.readUnsignedByte();
					in.readUnsignedShort();
					in.readUnsignedShort();
					in.readInt();
					in.readInt();
					in.readString();
					break;
				case 202:
					// decodeConditionalSubOp: byte, 3x short, int, int, string.
					in.readUnsignedByte();
					in.readUnsignedShort();
					in.readUnsignedShort();
					in.readUnsignedShort();
					in.readInt();
					in.readInt();
					in.readString();
					break;
				case 249:
					in.skipParams();
					break;
				default:
					throw new IllegalStateException("unknown item opcode " + opcode);
			}
		}

		// Mirror the dumper's wearable filter: only items with a worn model.
		if (maleModel0 == -1 && femaleModel0 == -1)
		{
			return null;
		}

		ModelRepository.Entry entry = new ModelRepository.Entry();
		entry.n = name;
		entry.mo = maleOffset;
		entry.fo = femaleOffset;
		entry.wp1 = wearPos1;
		entry.wp2 = wearPos2;
		entry.wp3 = wearPos3;
		entry.m = new int[]{maleModel0, maleModel1, maleModel2};
		entry.f = new int[]{femaleModel0, femaleModel1, femaleModel2};
		if (maleHead != -1 || maleHead2 != -1)
		{
			entry.hm = new int[]{maleHead, maleHead2};
		}
		if (femaleHead != -1 || femaleHead2 != -1)
		{
			entry.hf = new int[]{femaleHead, femaleHead2};
		}
		entry.cf = colorFind;
		entry.cr = colorReplace;
		entry.tf = textureFind;
		entry.tr = textureReplace;
		return entry;
	}

	// ------------------------------------------------------------------- kits

	static ModelRepository.Entry decodeKit(byte[] data, boolean[] nonSelectableOut)
	{
		Buffer in = new Buffer(data);
		Integer bodyPartId = null;
		int[] models = null;
		int[] chatheads = {-1, -1, -1, -1, -1};
		short[] recolorFind = null;
		short[] recolorReplace = null;
		short[] retextureFind = null;
		short[] retextureReplace = null;

		for (int opcode = in.readUnsignedByte(); opcode != 0; opcode = in.readUnsignedByte())
		{
			if (opcode == 1)
			{
				bodyPartId = in.readUnsignedByte();
			}
			else if (opcode == 2)
			{
				int count = in.readUnsignedByte();
				models = new int[count];
				for (int i = 0; i < count; i++)
				{
					models[i] = in.readUnsignedShort();
				}
			}
			else if (opcode == 3)
			{
				// Flagged non-selectable: character creation never offers this
				// style. No payload.
				nonSelectableOut[0] = true;
			}
			else if (opcode == 5)
			{
				int count = in.readUnsignedByte();
				models = new int[count];
				for (int i = 0; i < count; i++)
				{
					models[i] = in.readInt();
				}
			}
			else if (opcode == 40)
			{
				int count = in.readUnsignedByte();
				recolorFind = new short[count];
				recolorReplace = new short[count];
				for (int i = 0; i < count; i++)
				{
					// NOTE: signed shorts here, unlike items and spotanims.
					recolorFind[i] = (short) in.readShort();
					recolorReplace[i] = (short) in.readShort();
				}
			}
			else if (opcode == 41)
			{
				int count = in.readUnsignedByte();
				retextureFind = new short[count];
				retextureReplace = new short[count];
				for (int i = 0; i < count; i++)
				{
					retextureFind[i] = (short) in.readShort();
					retextureReplace[i] = (short) in.readShort();
				}
			}
			else if (opcode >= 60 && opcode < 70)
			{
				chatheads[opcode - 60] = in.readUnsignedShort();
			}
			else if (opcode >= 70 && opcode < 80)
			{
				chatheads[opcode - 70] = in.readInt();
			}
			else
			{
				throw new IllegalStateException("unknown kit opcode " + opcode);
			}
		}

		// Mirror the dumper's filter: kits without models are unusable.
		if (models == null || models.length == 0)
		{
			return null;
		}

		ModelRepository.Entry entry = new ModelRepository.Entry();
		entry.bp = bodyPartId;
		entry.m = models;
		entry.f = models;
		boolean anyHead = false;
		for (int head : chatheads)
		{
			anyHead |= head != -1;
		}
		if (anyHead)
		{
			entry.ch = chatheads;
		}
		entry.cf = recolorFind;
		entry.cr = recolorReplace;
		entry.tf = retextureFind;
		entry.tr = retextureReplace;
		return entry;
	}

	// -------------------------------------------------------------- spotanims

	private static SpotAnimRepository.Entry decodeSpotAnim(byte[] data)
	{
		Buffer in = new Buffer(data);
		int modelId = 0;
		int animationId = -1;
		int resizeX = 128;
		int resizeY = 128;
		int rotation = 0;
		int ambient = 0;
		int contrast = 0;
		short[] recolorFind = null;
		short[] recolorReplace = null;
		short[] retextureFind = null;
		short[] retextureReplace = null;

		for (int opcode = in.readUnsignedByte(); opcode != 0; opcode = in.readUnsignedByte())
		{
			switch (opcode)
			{
				case 1:
					modelId = in.readUnsignedShort();
					break;
				case 2:
					animationId = in.readUnsignedShort();
					break;
				case 3:
					modelId = in.readInt();
					break;
				case 4:
					resizeX = in.readUnsignedShort();
					break;
				case 5:
					resizeY = in.readUnsignedShort();
					break;
				case 6:
					rotation = in.readUnsignedShort();
					break;
				case 7:
					ambient = in.readUnsignedByte();
					break;
				case 8:
					contrast = in.readUnsignedByte();
					break;
				case 9:
					in.readString(); // debug name
					break;
				case 10:
					// A newer flag opcode with NO payload - proven empirically:
					// the offline dumper's library ignores unknown opcodes
					// without consuming bytes, and every affected definition
					// (39 of them, ids 3882+) still dumped perfectly clean.
					break;
				case 40:
				{
					int count = in.readUnsignedByte();
					recolorFind = new short[count];
					recolorReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						recolorFind[i] = (short) in.readUnsignedShort();
						recolorReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 41:
				{
					int count = in.readUnsignedByte();
					retextureFind = new short[count];
					retextureReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						retextureFind[i] = (short) in.readUnsignedShort();
						retextureReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				default:
					throw new IllegalStateException("unknown spotanim opcode " + opcode);
			}
		}

		// Mirror the dumper's filter: a spotanim without a model shows nothing.
		if (modelId <= 0)
		{
			return null;
		}

		SpotAnimRepository.Entry entry = new SpotAnimRepository.Entry();
		entry.m = modelId;
		entry.a = animationId;
		entry.rx = resizeX == 128 ? null : resizeX;
		entry.ry = resizeY == 128 ? null : resizeY;
		entry.rot = rotation == 0 ? null : rotation;
		entry.am = ambient == 0 ? null : ambient;
		entry.co = contrast == 0 ? null : contrast;
		entry.cf = recolorFind;
		entry.cr = recolorReplace;
		entry.tf = retextureFind;
		entry.tr = retextureReplace;
		return entry;
	}

	// ----------------------------------------------------------------- buffer

	/** Minimal big-endian reader matching runelite-cache's InputStream widths. */
	private static final class Buffer
	{
		private final byte[] data;
		private int offset;

		Buffer(byte[] data)
		{
			this.data = data;
		}

		int readUnsignedByte()
		{
			return data[offset++] & 0xFF;
		}

		int readByte()
		{
			return data[offset++];
		}

		int readUnsignedShort()
		{
			return (readUnsignedByte() << 8) | readUnsignedByte();
		}

		int readShort()
		{
			return (short) readUnsignedShort();
		}

		int read24BitInt()
		{
			return (readUnsignedByte() << 16) | (readUnsignedByte() << 8) | readUnsignedByte();
		}

		int readInt()
		{
			return (readUnsignedByte() << 24) | (readUnsignedByte() << 16)
				| (readUnsignedByte() << 8) | readUnsignedByte();
		}

		/**
		 * A 0-terminated string. Only item NAMES are kept, and those are
		 * plain CP1252; the special-character remapping the cache library
		 * applies affects codepoints 128-159, which item names do not use -
		 * anything in that range maps through the same table here for parity.
		 */
		String readString()
		{
			StringBuilder sb = new StringBuilder();
			for (int b = readUnsignedByte(); b != 0; b = readUnsignedByte())
			{
				if (b >= 128 && b < 160)
				{
					char mapped = CP1252_SPECIALS[b - 128];
					sb.append(mapped == 0 ? '?' : mapped);
				}
				else
				{
					sb.append((char) b);
				}
			}
			return sb.toString();
		}

		/** Skips a params map: count, then (isString byte, 24-bit key, value). */
		void skipParams()
		{
			int count = readUnsignedByte();
			for (int i = 0; i < count; i++)
			{
				boolean isString = readUnsignedByte() == 1;
				read24BitInt();
				if (isString)
				{
					readString();
				}
				else
				{
					readInt();
				}
			}
		}
	}

	/** Windows-1252's 0x80-0x9F block, as the cache text format defines it. */
	private static final char[] CP1252_SPECIALS = {
		'€', 0, '‚', 'ƒ', '„', '…', '†', '‡',
		'ˆ', '‰', 'Š', '‹', 'Œ', 0, 'Ž', 0,
		0, '‘', '’', '“', '”', '•', '–', '—',
		'˜', '™', 'š', '›', 'œ', 0, 'ž', 'Ÿ',
	};
}

package com.rapidursa.mounts.appearance;

import java.util.Arrays;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;

/**
 * The follower's appearance, stored in the same encoding the game uses for
 * {@link PlayerComposition#getEquipmentIds()}:
 *
 * <pre>
 *   0                     empty slot
 *   {@value #KIT_OFFSET} + kitId    a body kit (torso, arms, hair, ...)
 *   {@value #ITEM_OFFSET} + itemId  an equipped item
 * </pre>
 *
 * Slot order is {@link KitType#getIndex()}: HEAD, CAPE, AMULET, WEAPON, TORSO,
 * SHIELD, ARMS, LEGS, HAIR, HANDS, BOOTS, JAW.
 */
public final class Outfit
{
	/**
	 * Internal encoding offsets, spaced so the kit and item ranges cannot collide.
	 * The game encoding is produced and consumed only at the boundary, in
	 * {@link #toGameEquipmentIds()} and {@link #from(PlayerComposition)}.
	 */
	public static final int KIT_OFFSET = 1 << 20;
	public static final int ITEM_OFFSET = 1 << 21;
	public static final int SLOTS = 12;

	/**
	 * The game's own offsets, used only when talking to PlayerComposition: a slot
	 * holds {@code 0} for empty, {@code 256 + kitId} for a kit, and
	 * {@code 2048 + itemId} for an item.
	 *
	 * <p>The item offset is 2048, not 512. That leaves kit ids room to run up to
	 * 1791, which they need - hair and jaw kits are past 300. With 512 here, kit 305
	 * encoded to 561, which reads back as item 49, and every kit above 255 was
	 * silently corrupted in both directions: live compositions decoded into
	 * nonexistent items, and the capture path swapped garbage into the player.
	 */
	private static final int GAME_KIT_OFFSET = PlayerComposition.KIT_OFFSET;
	private static final int GAME_ITEM_OFFSET = PlayerComposition.ITEM_OFFSET;

	/**
	 * Default identikit ids, used to fill body slots the outfit leaves empty so
	 * the follower isn't a floating head. These are the standard character
	 * creation kits; if your dump shows different ids, adjust here.
	 */
	private static final int[][] DEFAULT_KITS_MALE = {
		{KitType.HAIR.getIndex(), 0},
		// The jaw kit is facial geometry, not merely a beard - without one the head
		// renders incomplete, so both genders always get a default.
		{KitType.JAW.getIndex(), 10},
		{KitType.TORSO.getIndex(), 18},
		{KitType.ARMS.getIndex(), 26},
		{KitType.HANDS.getIndex(), 33},
		{KitType.LEGS.getIndex(), 36},
		{KitType.BOOTS.getIndex(), 42},
	};

	private static final int[][] DEFAULT_KITS_FEMALE = {
		{KitType.HAIR.getIndex(), 45},
		// Female jaw kits are 292-306 with their own distinct models. They only ever
		// looked broken because ids above 255 overflowed the old slot encoding.
		{KitType.JAW.getIndex(), 292},
		{KitType.TORSO.getIndex(), 56},
		{KitType.ARMS.getIndex(), 61},
		{KitType.HANDS.getIndex(), 67},
		{KitType.LEGS.getIndex(), 70},
		{KitType.BOOTS.getIndex(), 79},
	};

	private final int[] equipment = new int[SLOTS];
	private final int[] colors = new int[5];
	private int gender;

	public Outfit()
	{
	}

	public Outfit(Outfit other)
	{
		copyFrom(other);
	}

	public static Outfit from(PlayerComposition composition)
	{
		Outfit outfit = new Outfit();
		if (composition == null)
		{
			return outfit;
		}

		int[] ids = composition.getEquipmentIds();
		if (ids != null)
		{
			for (int i = 0; i < Math.min(ids.length, SLOTS); i++)
			{
				int raw = ids[i];
				if (raw >= GAME_ITEM_OFFSET)
				{
					outfit.equipment[i] = ITEM_OFFSET + (raw - GAME_ITEM_OFFSET);
				}
				else if (raw >= GAME_KIT_OFFSET)
				{
					outfit.equipment[i] = KIT_OFFSET + (raw - GAME_KIT_OFFSET);
				}
				else
				{
					outfit.equipment[i] = 0;
				}
			}
		}
		outfit.setColors(composition.getColors());
		outfit.setGender(composition.getGender());
		return outfit;
	}

	public int[] rawEquipment()
	{
		return equipment.clone();
	}

	/**
	 * This outfit in the game's own composition encoding, for writing back into a
	 * live {@code PlayerComposition}.
	 *
	 * <p>The scheme holds kit ids up to 1791 before they would overflow into the item
	 * range; anything beyond that is dropped rather than written as a corrupt value.
	 * No real kit comes close, so in practice nothing is lost.
	 */
	public int[] toGameEquipmentIds()
	{
		int[] out = new int[SLOTS];
		for (int i = 0; i < SLOTS; i++)
		{
			int value = equipment[i];
			if (value >= ITEM_OFFSET)
			{
				out[i] = GAME_ITEM_OFFSET + (value - ITEM_OFFSET);
			}
			else if (value >= KIT_OFFSET)
			{
				int kitId = value - KIT_OFFSET;
				out[i] = kitId < (GAME_ITEM_OFFSET - GAME_KIT_OFFSET)
					? GAME_KIT_OFFSET + kitId
					: 0;
			}
			else
			{
				out[i] = 0;
			}
		}
		return out;
	}

	public int getRaw(KitType slot)
	{
		return equipment[slot.getIndex()];
	}

	public void setRaw(KitType slot, int raw)
	{
		equipment[slot.getIndex()] = raw;
	}

	public void setItem(KitType slot, int itemId)
	{
		equipment[slot.getIndex()] = itemId <= 0 ? 0 : ITEM_OFFSET + itemId;
	}

	public void setKit(KitType slot, int kitId)
	{
		equipment[slot.getIndex()] = kitId < 0 ? 0 : KIT_OFFSET + kitId;
	}

	public void clear(KitType slot)
	{
		equipment[slot.getIndex()] = 0;
	}

	public boolean isItem(KitType slot)
	{
		return equipment[slot.getIndex()] >= ITEM_OFFSET;
	}

	public boolean isKit(KitType slot)
	{
		int v = equipment[slot.getIndex()];
		return v >= KIT_OFFSET && v < ITEM_OFFSET;
	}

	public int itemId(KitType slot)
	{
		return equipment[slot.getIndex()] - ITEM_OFFSET;
	}

	public int kitId(KitType slot)
	{
		return equipment[slot.getIndex()] - KIT_OFFSET;
	}

	public int getGender()
	{
		return gender;
	}

	public void setGender(int gender)
	{
		this.gender = gender == 1 ? 1 : 0;
	}

	public int[] getColors()
	{
		return colors.clone();
	}

	public void setColors(int[] source)
	{
		if (source != null)
		{
			System.arraycopy(source, 0, colors, 0, Math.min(source.length, colors.length));
		}
	}

	public void copyFrom(Outfit other)
	{
		System.arraycopy(other.equipment, 0, equipment, 0, SLOTS);
		System.arraycopy(other.colors, 0, colors, 0, colors.length);
		gender = other.gender;
	}

	/**
	 * Returns a copy with empty body slots filled by default kits. Item slots and
	 * already-populated kit slots are untouched, so gear always wins.
	 */
	/** The default kit id for a body part, or -1 if that part has no default. */
	public static int defaultKitId(KitType slot, int gender)
	{
		for (int[] pair : (gender == 1 ? DEFAULT_KITS_FEMALE : DEFAULT_KITS_MALE))
		{
			if (pair[0] == slot.getIndex())
			{
				return pair[1];
			}
		}
		return -1;
	}

	public Outfit withDefaultBody()
	{
		Outfit filled = new Outfit(this);

		// Every body kit is filled here, including ones the gear will cover. Which of
		// them actually render is decided at compose time from each item's wearPos
		// data, the same way the game does it - a platebody hides the arms but a
		// chainbody does not, and only the item itself knows which it is. Deciding
		// that here, by slot type alone, stripped the arms under every torso item.
		for (int[] pair : (gender == 1 ? DEFAULT_KITS_FEMALE : DEFAULT_KITS_MALE))
		{
			if (pair[1] >= 0 && filled.equipment[pair[0]] == 0)
			{
				filled.equipment[pair[0]] = KIT_OFFSET + pair[1];
			}
		}
		return filled;
	}

	public boolean isEmpty()
	{
		for (int v : equipment)
		{
			if (v != 0)
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof Outfit))
		{
			return false;
		}
		Outfit other = (Outfit) o;
		return gender == other.gender
			&& Arrays.equals(equipment, other.equipment)
			&& Arrays.equals(colors, other.colors);
	}

	@Override
	public int hashCode()
	{
		return 31 * (31 * Arrays.hashCode(equipment) + Arrays.hashCode(colors)) + gender;
	}

	@Override
	public String toString()
	{
		StringBuilder sb = new StringBuilder();
		for (KitType slot : KitType.values())
		{
			int v = getRaw(slot);
			if (v == 0)
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(slot.name()).append('=')
				.append(v >= ITEM_OFFSET ? "item:" + (v - ITEM_OFFSET) : "kit:" + (v - KIT_OFFSET));
		}

		if (gender == 1)
		{
			sb.append(sb.length() > 0 ? "," : "").append("gender=female");
		}

		// Body-colour indices into the game's palette tables; the parser already
		// reads this key, but until 2026-08-02 nothing wrote it, so panel-chosen
		// indices silently vanished on every save.
		boolean anyColor = false;
		for (int c : colors)
		{
			if (c != 0)
			{
				anyColor = true;
				break;
			}
		}
		if (anyColor)
		{
			sb.append(sb.length() > 0 ? "," : "").append("colors=");
			for (int i = 0; i < colors.length; i++)
			{
				if (i > 0)
				{
					sb.append('/');
				}
				sb.append(colors[i]);
			}
		}

		return sb.toString();
	}
}

package com.rapidursa.mounts;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

@Singleton
final class ArtioAnchorOverlay extends Overlay
{
    private static final int LABEL_COUNT = 60;

    private final Client client;
    private final RapidUrsaMountsConfig config;
    private RapidUrsaMountsPlugin plugin;

    @Inject
    ArtioAnchorOverlay(Client client, RapidUrsaMountsConfig config)
    {
        this.client = client;
        this.config = config;
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPosition(OverlayPosition.DYNAMIC);
    }

    void bind(RapidUrsaMountsPlugin plugin)
    {
        this.plugin = plugin;
    }

    void unbind()
    {
        plugin = null;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showArtioAnchorProbe())
        {
            return null;
        }

        RuneLiteObject artio = plugin == null ? null : plugin.getArtioObjectForProbe();
        Model model = artio == null ? null : artio.getModel();
        LocalPoint origin = artio == null ? null : artio.getLocation();
        if (model == null || origin == null)
        {
            return null;
        }

        float[] xs = model.getVerticesX();
        float[] ys = model.getVerticesY();
        float[] zs = model.getVerticesZ();
        int start = Math.min(config.artioAnchorProbeStart(), model.getVerticesCount());
        int spacing = Math.max(1, config.artioAnchorProbeSpacing());
        int orientation = artio.getOrientation();
        int plane = artio.getLevel();
        Font previousFont = graphics.getFont();
        graphics.setFont(previousFont.deriveFont(Font.BOLD, 11f));

        int shown = 0;
        for (int vertex = start; vertex < model.getVerticesCount() && shown < LABEL_COUNT; vertex += spacing)
        {
            LocalPoint point = RapidUrsaMountsPlugin.offsetFromPlayer(
                origin, orientation, -Math.round(zs[vertex]), Math.round(xs[vertex]));
            Point canvas = Perspective.localToCanvas(client, point, plane, -Math.round(ys[vertex]));
            if (canvas != null)
            {
                Color color = (shown & 1) == 0 ? Color.CYAN : Color.YELLOW;
                graphics.setColor(color);
                graphics.fillOval(canvas.getX() - 2, canvas.getY() - 2, 5, 5);
                OverlayUtil.renderTextLocation(graphics,
                    new Point(canvas.getX() + 4, canvas.getY() - 3),
                    Integer.toString(vertex), color);
            }
            shown++;
        }
        graphics.setFont(previousFont);
        return null;
    }
}

package com.rapidursa.mounts;

import java.util.function.BooleanSupplier;
import java.util.function.IntSupplier;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;

/**
 * Lifts the flying red dragon's animated tail into the line of the torso while
 * the player is moving. Animation 7870 bends the tail sharply downward even
 * though the rest of the dragon travels level. The correction is feathered
 * out from the tail root so the join stays smooth and the animation can still
 * flex the tail naturally.
 */
final class DragonTailFollowAnimationController extends AnimationController
{
    private static final float TAIL_ROOT_Z = 68f;
    private static final float FULL_LIFT_Z = 145f;
    private static final float MAX_TAIL_HALF_WIDTH = 58f;
    private static final float ROOT_BAND = 22f;

    private final BooleanSupplier moving;
    private final IntSupplier liftDegrees;

    DragonTailFollowAnimationController(Client client, int animationId,
        BooleanSupplier moving, IntSupplier liftDegrees)
    {
        super(client, animationId);
        this.moving = moving;
        this.liftDegrees = liftDegrees;
    }

    @Override
    public Model animate(Model model, AnimationController other)
    {
        Model animated = super.animate(model, other);
        int degrees = Math.max(0, Math.min(50, liftDegrees.getAsInt()));
        if (animated == null || !moving.getAsBoolean() || degrees == 0)
        {
            return animated;
        }

        int count = Math.min(model.getVerticesCount(), animated.getVerticesCount());
        if (count == 0)
        {
            return animated;
        }

        float[] baseX = model.getVerticesX();
        float[] baseY = model.getVerticesY();
        float[] baseZ = model.getVerticesZ();
        float[] y = animated.getVerticesY();
        float[] z = animated.getVerticesZ();

        float baseRootY = 0f;
        float animatedRootY = 0f;
        float animatedRootZ = 0f;
        int rootCount = 0;
        for (int vertex = 0; vertex < count; vertex++)
        {
            if (Math.abs(baseX[vertex]) <= 34f
                && Math.abs(baseZ[vertex] - TAIL_ROOT_Z) <= ROOT_BAND)
            {
                baseRootY += baseY[vertex];
                animatedRootY += y[vertex];
                animatedRootZ += z[vertex];
                rootCount++;
            }
        }
        if (rootCount == 0)
        {
            return animated;
        }

        baseRootY /= rootCount;
        animatedRootY /= rootCount;
        animatedRootZ /= rootCount;

        for (int vertex = 0; vertex < count; vertex++)
        {
            if (baseZ[vertex] <= TAIL_ROOT_Z
                || Math.abs(baseX[vertex]) > MAX_TAIL_HALF_WIDTH
                || Math.abs(baseY[vertex] - baseRootY) > 52f)
            {
                continue;
            }

            double weight = Math.min(1.0,
                (baseZ[vertex] - TAIL_ROOT_Z) / (FULL_LIFT_Z - TAIL_ROOT_Z));
            // Smoothstep keeps the torso-to-tail join free of a visible kink.
            weight = weight * weight * (3.0 - 2.0 * weight);
            double radians = Math.toRadians(degrees * weight);
            double sin = Math.sin(radians);
            double cos = Math.cos(radians);
            double dy = y[vertex] - animatedRootY;
            double dz = z[vertex] - animatedRootZ;
            y[vertex] = (float) (animatedRootY + dy * cos - dz * sin);
            z[vertex] = (float) (animatedRootZ + dy * sin + dz * cos);
        }
        return animated;
    }
}

