    @Override
    protected void shutDown()
    {
        setHolsterHandoff(false);
        mountedRenderReady = false;
        hooks.unregisterRenderableDrawListener(drawListener);
        if (stableNavigation != null)
        {
            clientToolbar.removeNavigation(stableNavigation);
            stableNavigation = null;
        }
        mountStablePanel.unbind();
        keyManager.unregisterKeyListener(mountHotkey);
        mouseManager.unregisterMouseListener(mountButton);
        mouseManager.unregisterMouseListener(battleReadyButton);
        mouseManager.unregisterMouseListener(dragonLandingButton);
        overlayManager.remove(mountButton);
        overlayManager.remove(battleReadyButton);
        overlayManager.remove(dragonLandingButton);
        overlayManager.remove(artioAnchorOverlay);
        artioAnchorOverlay.unbind();
        mountButton.unbind();
        battleReadyButton.unbind();
        dragonLandingButton.unbind();
        despawn();
        clearEffects();
        mounted = false;
        dragonDismountPending = false;
        dragonRemountFlying = false;
        dragonCombatReturnToFlight = false;
        dragonCombatGroundVisibleUntilNanos = 0L;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            // Region/instance loads pass through LOADING. Keep flight and any
            // queued landing intact so rebuilding the RuneLite objects after
            // the map loads does not silently swap the dragon to ground form.
            if (event.getGameState() == GameState.LOGIN_SCREEN)
            {
                dragonDismountPending = false;
                dragonRemountFlying = false;
                dragonCombatReturnToFlight = false;
                dragonCombatGroundVisibleUntilNanos = 0L;
                dragonInteractionPendingUntilNanos = 0L;
                dragonTransitioning = false;
                dragonLanded = true;
            }
            despawn();
            clearEffects();
        }
    }

