    @Subscribe
    public void onBeforeRender(BeforeRender event)
    {
        mountedRenderReady = false;
        if (!mounted || !config.enabled() || client.getGameState() != GameState.LOGGED_IN)
        {
            setHolsterHandoff(false);
            if (mountedHolsterRenderer != null) mountedHolsterRenderer.clear();
            return;
        }

        Player player = client.getLocalPlayer();
        if (player == null || player.getLocalLocation() == null)
        {
            setHolsterHandoff(false);
            return;
        }

        // Engage before the first swing so the visible descent finishes before
        // the normal action pause hides the cosmetic rider during combat.
        net.runelite.api.Actor target = player.getInteracting();
        boolean combatTarget = target instanceof Player
            || (target instanceof net.runelite.api.NPC
                && ((net.runelite.api.NPC) target).getComposition() != null
                && ((net.runelite.api.NPC) target).getComposition().getCombatLevel() > 0);
        if (config.mountType() == MountType.FLYING_DRAGON && !dragonLanded
            && !dragonTransitioning && !dragonDismountPending
            && combatTarget)
        {
            dragonCombatReturnToFlight = true;
            toggleDragonLanding();
        }

        if (dragonTransitioning
            && System.nanoTime() - dragonTransitionStartNanos >= DRAGON_TRANSITION_NANOS)
        {
            dragonTransitioning = false;
            if (dragonDescending)
            {
                // The flying body has reached the ground; now show NPC 8079.
                dragonLanded = true;
                flyingDragonRiderAnchor.reset();
                if (dragonCombatReturnToFlight)
                {
                    // Show at least a few frames of the ground form at the
                    // end of the descent before yielding to the real attack.
                    dragonCombatGroundVisibleUntilNanos = System.nanoTime() + 300_000_000L;
                }
                if (dragonDismountPending)
                {
                    dragonDismountPending = false;
                    finishDismount();
                    return;
                }
                despawn();
            }
            else if (dragonDismountPending)
            {
                // A dismount pressed during takeoff waits for the ascent to
                // finish, then plays the full landing before dismissing.
                toggleDragonLanding();
            }
        }

        // Claim the weapon before either plugin draws this frame. Holster's
        // on-foot object must not remain active while the mounted rider moves.
        boolean mountedHolsterActive = config.mountedHolster()
            && holsterSettings.holstered() && isMountedHolsterCompatible();
        setHolsterHandoff(mountedHolsterActive);

        // Keep only the Terrorbird mounted while the real player fights.
        // The server still owns every attack, target and hit; this is visual.
        boolean terrorbirdFighting = config.mountType() == MountType.TERRORBIRD
            && config.terrorbirdMountedCombat()
            && player.getInteracting() != null;
        if (terrorbirdFighting)
        {
            actionResumeTicks = 0;
            terrorbirdCombatGraceTicks = 3;
        }
        else
        {
            lastTerrorbirdAttackFrame = -1;
        }
        boolean finishingTerrorbirdAttack = config.mountType() == MountType.TERRORBIRD
            && config.terrorbirdMountedCombat() && terrorbirdCombatGraceTicks > 0;
        boolean manualBattleReady = terrorbirdBattleReady
            && config.mountType() == MountType.TERRORBIRD
            && config.ridingPose() == RidingPose.STANDARD;
        terrorbirdCombatActive = terrorbirdFighting || finishingTerrorbirdAttack
            || manualBattleReady;
        terrorbirdAttackAnimation = (terrorbirdFighting || finishingTerrorbirdAttack)
            ? player.getAnimation() : -1;
        if (terrorbirdAttackAnimation >= 0)
        {
            terrorbirdHeldCombatAnimation = terrorbirdAttackAnimation;
        }
        else if (!terrorbirdCombatActive)
        {
            terrorbirdHeldCombatAnimation = -1;
        }

        Widget npcDialogue = client.getWidget(InterfaceID.ChatLeft.TEXT);
        Widget playerDialogue = client.getWidget(InterfaceID.ChatRight.TEXT);
        Widget dialogueOptions = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
        boolean dialogueOpen = (npcDialogue != null && !npcDialogue.isHidden())
            || (playerDialogue != null && !playerDialogue.isHidden())
            || (dialogueOptions != null && !dialogueOptions.isHidden());
        if (dragonCombatReturnToFlight && (player.getAnimation() != -1 || dialogueOpen))
        {
            dragonInteractionPendingUntilNanos = 0L;
        }
        boolean landingForCombat = dragonCombatReturnToFlight
            && (dragonTransitioning && dragonDescending
                || System.nanoTime() < dragonCombatGroundVisibleUntilNanos);
        if (dragonCombatReturnToFlight
            && (target != null || player.getAnimation() != -1 || dialogueOpen))
        {
            actionResumeTicks = config.actionResumeDelay();
        }
        if ((config.pauseForActions() || dragonCombatReturnToFlight)
            && !terrorbirdFighting && !finishingTerrorbirdAttack && !landingForCombat)
        {
            if (player.getAnimation() != -1 || player.getInteracting() != null || dialogueOpen)
            {
                actionResumeTicks = config.actionResumeDelay();
                suspendCosmetics();
                return;
            }
            if (actionResumeTicks > 0)
            {
                suspendCosmetics();
                return;
            }
        }

        if (dragonCombatReturnToFlight && dragonLanded && !dragonTransitioning
            && target == null && player.getAnimation() == -1 && !dialogueOpen
            && actionResumeTicks == 0
            && System.nanoTime() >= dragonInteractionPendingUntilNanos
            && System.nanoTime() >= dragonCombatGroundVisibleUntilNanos)
        {
            dragonCombatReturnToFlight = false;
            dragonCombatGroundVisibleUntilNanos = 0L;
            dragonInteractionPendingUntilNanos = 0L;
            toggleDragonLanding();
        }

        if (!ensureObjects())
        {
            setHolsterHandoff(false);
            return;
        }

        LocalPoint playerPoint = player.getLocalLocation();
        int plane = player.getWorldLocation().getPlane();
        int orientation = player.getCurrentOrientation();
        int zukMountForward = config.mountType() == MountType.TZREK_ZUK
            ? config.zukMountForward() : 0;
        LocalPoint mountPoint = zukMountForward == 0
            ? playerPoint
            : offsetFromPlayer(playerPoint, orientation, zukMountForward, 0);
        int terrainZ = Perspective.getTileHeight(client, mountPoint, plane);
        // Rapid Holster temporarily replaces the player's pose set while it owns
        // the on-foot weapon. That pose can survive for part of the mounted
        // handoff and report "walking" after the player has stopped. Track real
        // local movement instead so mount, rider, and weapon share one state.
        boolean moving = isPlayerMoving(playerPoint);
        mountMoving = moving;

        // The custom saddle and rider are separate RuneLite objects, so give them
        // one shared seat transform to keep them visually locked together.
        int linkedSeatForward = 0;
        int linkedSeatSideways = 0;
        int linkedSeatHeight = 0;
        if (config.mountType() == MountType.BLACK_UNICORN)
        {
            if (moving)
            {
                double phase = currentStridePhase();
                if (phase >= 0)
                {
                    linkedSeatForward = (int) Math.round(2.0 * Math.sin(phase));
                    linkedSeatSideways = (int) Math.round(Math.cos(phase));
                    linkedSeatHeight = (int) Math.round(3.0 * (0.5 - 0.5 * Math.cos(phase)));
                }
            }
            else
            {
                linkedSeatHeight = currentIdleBounce();
            }
        }

        if (config.mountType() == MountType.TERRORBIRD)
        {
            // Probe the bird's central back, not the rider's pose-specific
            // location, which can sit above the head in model space.
            updateRiderAnchor(terrorbirdRiderAnchor, 0, 80, 0);
        }

        unicorn.setLocation(mountPoint, plane);
        unicorn.setZ(terrainZ - currentDragonBodyHeight());
        unicorn.setOrientation(orientation);
        for (RuneLiteObject part : mountParts)
        {
            part.setLocation(mountPoint, plane);
            part.setZ(terrainZ);
            part.setOrientation(orientation);
        }
        if (saddle != null)
        {
            int saddleForward;
            int saddleSideways;
            int saddleHeight;
            if (config.mountType() == MountType.GRYPHON)
            {
                saddleForward = config.gryphonSaddleForward();
                saddleSideways = config.gryphonSaddleSideways();
                saddleHeight = config.gryphonSaddleHeight();
                currentGryphonSaddleForward = saddleForward;
                currentGryphonSaddleSideways = saddleSideways;
                currentGryphonSaddleHeight = saddleHeight;
            }
            else if (config.mountType() == MountType.TERRORBIRD)
            {
                saddleForward = currentRiderForward() + config.terrorbirdSeatSaddleForward()
                    + (moving ? TERRORBIRD_WALK_SEAT_BACK : 0);
                saddleSideways = currentRiderSideways() + config.terrorbirdSeatSaddleSideways();
                saddleHeight = currentRiderHeight() - 10 + config.terrorbirdSeatSaddleHeight();
                if (moving && terrorbirdRiderAnchor.moving)
                {
                    saddleForward += terrorbirdRiderAnchor.forward;
                    saddleSideways += terrorbirdRiderAnchor.sideways;
                    saddleHeight += terrorbirdRiderAnchor.height;
                }
                else if (!moving)
                {
                    // The rider uses this same idle lift below. Sharing it
                    // keeps the independent saddle object locked to the seat.
                    saddleHeight += currentIdleBounce();
                }
                currentTerrorbirdSaddleForward = saddleForward;
                currentTerrorbirdSaddleSideways = saddleSideways;
                currentTerrorbirdSaddleHeight = saddleHeight;
            }
            else if (config.mountType() == MountType.BATTLE_TURTLE)
            {
                saddleForward = config.battleTurtleSaddleForward() + linkedSeatForward;
                saddleSideways = config.battleTurtleSaddleSideways() + linkedSeatSideways;
                saddleHeight = config.battleTurtleSaddleHeight() + linkedSeatHeight;
                saddleHeight += moving ? currentSeatBounce() : currentIdleBounce();
            }
            else if (config.mountType() == MountType.ARTIO)
            {
                saddleForward = config.artioArmourForward();
                saddleSideways = config.artioArmourSideways();
                saddleHeight = config.artioArmourHeight();
                if (moving)
                {
                    saddleForward += currentWalkForwardAdjustment();
                    saddleHeight += currentWalkHeightAdjustment() + currentSeatBounce();
                }
                else
                {
                    saddleHeight += currentIdleBounce();
                }
                currentArtioSaddleForward = saddleForward;
                currentArtioSaddleSideways = saddleSideways;
                currentArtioSaddleHeight = saddleHeight;
            }
            else
            {
                saddleForward = config.saddleForward() + linkedSeatForward;
                saddleSideways = config.saddleSideways() + linkedSeatSideways;
                saddleHeight = config.saddleHeight() + linkedSeatHeight;
                if (config.mountType() == MountType.TERRORBIRD && moving)
                {
                    saddleForward += TERRORBIRD_WALK_SEAT_BACK;
                }
                if (config.mountType() == MountType.TERRORBIRD
                    && moving && terrorbirdRiderAnchor.moving)
                {
                    saddleForward += terrorbirdRiderAnchor.forward;
                    saddleSideways += terrorbirdRiderAnchor.sideways;
                    saddleHeight += terrorbirdRiderAnchor.height;
                }
            }
            LocalPoint saddlePoint = offsetFromPlayer(
                playerPoint,
                orientation,
                saddleForward,
                saddleSideways);
            saddle.setLocation(saddlePoint, plane);
            saddle.setZ(Perspective.getTileHeight(client, saddlePoint, plane)
                - saddleHeight);
            saddle.setOrientation(orientation);
            if (terrorbirdReins != null)
            {
                terrorbirdReins.setLocation(saddlePoint, plane);
                terrorbirdReins.setZ(Perspective.getTileHeight(client, saddlePoint, plane)
                    - saddleHeight);
                terrorbirdReins.setOrientation(orientation);
            }
            if (artioShield != null)
            {
                artioShield.setLocation(saddlePoint, plane);
                artioShield.setZ(Perspective.getTileHeight(client, saddlePoint, plane)
                    - saddleHeight);
                artioShield.setOrientation(orientation);
            }
            positionArtioAttachment(artioWarspears, saddlePoint, plane, saddleHeight, orientation);
        }

        if (config.animateUnicorn())
        {
            int wantedAnimation = currentWalkOrIdleAnimation(moving);
            if (wantedAnimation != activeUnicornAnimation)
            {
                unicorn.setAnimationController(wantedAnimation < 0
                    ? null : loopingMountAnimation(wantedAnimation));
                for (RuneLiteObject part : mountParts)
                {
                    part.setAnimationController(wantedAnimation < 0
                        ? null : loopingAnimation(wantedAnimation));
                }
                activeUnicornAnimation = wantedAnimation;
            }
        }
        else if (activeUnicornAnimation != -1)
        {
            unicorn.setAnimationController(null);
            for (RuneLiteObject part : mountParts)
            {
                part.setAnimationController(null);
            }
            activeUnicornAnimation = -1;
        }

        if (config.mountType() == MountType.TERRORBIRD && saddle != null)
        {
            updateTerrorbirdSaddle(moving);
        }
        else if (config.mountType() == MountType.GRYPHON && saddle != null)
        {
            updateGryphonSaddle();
        }
        else if (config.mountType() == MountType.ARTIO && saddle != null)
        {
            updateArtioArmour();
        }
        if (config.mountType() == MountType.ARAXXOR)
        {
            updateAraxxorRiderAnchor();
        }
        else if (config.mountType() == MountType.VORKATH)
        {
            updateVorkathRiderAnchor();
        }
        else if (config.mountType() == MountType.BIG_WOLF)
        {
            updateBackRiderAnchor(bigWolfRiderAnchor,
                config.bigWolfRiderSideways(), config.bigWolfRiderHeight(), config.bigWolfRiderForward());
        }
        else if (config.mountType() == MountType.SHEEP)
        {
            updateSheepRiderAnchor(sheepRiderAnchor,
                config.sheepRiderSideways(), config.sheepRiderHeight(), config.sheepRiderForward());
        }
        else if (config.mountType() == MountType.TZREK_ZUK)
        {
            // Select a fixed cluster at the shoulder on the base mesh, then
            // follow the same vertices through the pet's idle and walk frames.
            updateSheepRiderAnchor(zukShoulderAnchor,
                currentRiderSideways(), currentRiderHeight(), currentRiderForward());
        }
        else if (config.mountType() == MountType.FLYING_DRAGON && !dragonLanded)
        {
            // The fitted rider is well above the dragon's body. Probing at
            // rider height can select a wing instead of the central back.
            updateSheepRiderAnchor(flyingDragonRiderAnchor,
                0, 65, 0);
        }

        if (saddle != null && saddleMotionModels != null)
        {
            int motionFrame = 0;
            AnimationController controller = unicorn == null ? null : unicorn.getAnimationController();
            Animation animation = controller == null ? null : controller.getAnimation();
            if (!moving && animation != null && animation.getNumFrames() > 1)
            {
                // The complete ready animation contains four small muzzle
                // loops followed by a separate deep bow. Map the saddle to
                // that full source sequence so the bow cannot drift out of
                // sync with the unicorn.
                int sourceFrameCount = animation.getNumFrames();
                int sourceFrame = Math.floorMod(controller.getFrame(), sourceFrameCount);
                int unshiftedFrame = (int) Math.round(
                    sourceFrame * (saddleMotionModels.length - 1.0) / (sourceFrameCount - 1.0));
                // Shift the complete idle sequence, rather than wrapping the
                // timing adjustment inside the current 32-frame section. The
                // old section-local shift could change the bow's shape after
                // it began, but could never make the reins enter the bow early
                // enough to follow the unicorn's initial head dip.
                motionFrame = Math.floorMod(
                    unshiftedFrame + config.reinBobTiming(),
                    saddleMotionModels.length);
            }
            else
            {
                double phase = currentStridePhase();
                if (phase >= 0)
                {
                    double baseFrame = phase * REIN_LOOP_FRAMES / (2.0 * Math.PI);
                    motionFrame = Math.floorMod(
                        (int) Math.round(baseFrame * config.reinBobSpeedPercent() / 100.0)
                            + config.reinBobTiming(),
                        REIN_LOOP_FRAMES);
                }
            }
            if (motionFrame != activeSaddleMotionFrame)
            {
                saddle.setModel(saddleMotionModels[motionFrame]);
                activeSaddleMotionFrame = motionFrame;
            }
        }

        if (config.mountType() == MountType.BLACK_UNICORN
            && saddle != null && config.useCustomSaddle())
        {
            updateUnicornSaddle(linkedSeatForward, linkedSeatSideways, linkedSeatHeight);
        }

        boolean riderReady = false;
        if (config.showRider())
        {
            Model playerModel = buildRiderModel(player);
            if (playerModel != null)
            {
                int riderForward = currentRiderForward() + linkedSeatForward + currentDragonMatchForward();
                if (config.mountType() == MountType.TERRORBIRD && moving)
                {
                    riderForward += TERRORBIRD_WALK_SEAT_BACK;
                }
                int riderSideways = currentRiderSideways() + linkedSeatSideways + currentDragonMatchSideways();
                int riderHeight = currentRiderHeight() + linkedSeatHeight
                    + currentDragonFlightHeight();
                if (config.mountType() == MountType.FLYING_DRAGON && dragonTransitioning)
                {
                    riderHeight += (int) Math.round((config.landedDragonRiderHeight()
                        - config.flyingDragonRiderHeight()) * dragonLandingMatchFraction());
                }
                if (config.mountType() == MountType.TERRORBIRD
                    && config.ridingPose() == RidingPose.STANDARD)
                {
                    riderForward += config.terrorbirdSeatRiderForward();
                    riderSideways += config.terrorbirdSeatRiderSideways();
                    riderHeight += config.terrorbirdSeatRiderHeight();
                }
                if (config.mountType() == MountType.ARTIO)
                {
                    // Use the exact same animated upper-torso vertex delta as
                    // Artio's saddle mesh. This keeps the rider physically locked
                    // to the seat throughout both idle and walking animations.
                    riderForward += currentArtioSeatForward;
                    riderSideways += currentArtioSeatSideways;
                    riderHeight += currentArtioSeatHeight;
                }
                if (config.mountType() == MountType.GRYPHON)
                {
                    // Share the Gryphon back vertex delta with the complete
                    // saddle so the rider cannot drift above or through it.
                    riderForward += currentGryphonSeatForward;
                    riderSideways += currentGryphonSeatSideways;
                    riderHeight += currentGryphonSeatHeight;
                }
                if (config.mountType() == MountType.ARAXXOR)
                {
                    // Follow a cluster of animated back vertices instead of
                    // approximating the spider's motion with a sine wave.
                    riderForward += currentAraxxorSeatForward;
                    riderSideways += currentAraxxorSeatSideways;
                    riderHeight += currentAraxxorSeatHeight;
                }
                if (config.mountType() == MountType.VORKATH)
                {
                    // Share Vorkath's animated back movement with the rider and
                    // the mounted holster position derived from this rider point.
                    riderForward += currentVorkathSeatForward;
                    riderSideways += currentVorkathSeatSideways;
                    riderHeight += currentVorkathSeatHeight;
                }
                if (config.mountType() == MountType.BIG_WOLF)
                {
                    riderForward += bigWolfRiderAnchor.forward;
                    riderSideways += bigWolfRiderAnchor.sideways;
                    riderHeight += bigWolfRiderAnchor.height;
                }
                if (config.mountType() == MountType.SHEEP)
                {
                    riderForward += sheepRiderAnchor.forward;
                    riderSideways += sheepRiderAnchor.sideways;
                    riderHeight += sheepRiderAnchor.height;
                    if (moving)
                    {
                        // Sheep?'s walk twists the body from side to side.
                        // Follow the same animation clock even when its mesh
                        // has little displacement at the sampled back vertices.
                        double phase = currentSheepWalkPhase();
                        if (phase >= 0)
                        {
                            riderSideways += (int) Math.round(8.0 * Math.sin(phase));
                            riderHeight += (int) Math.round(3.0 * Math.abs(Math.sin(phase)));
                        }
                    }
                }
                if (config.mountType() == MountType.TZREK_ZUK)
                {
                    riderForward += zukShoulderAnchor.forward;
                    riderSideways += zukShoulderAnchor.sideways;
                    riderHeight += zukShoulderAnchor.height;
                }
                if (config.mountType() == MountType.FLYING_DRAGON && !dragonLanded)
                {
                    // Keep following the same animated back patch while descending.
                    // Fade the local bob to zero at the ground-model handoff so
                    // the rider arrives at the ground rider's exact coordinates.
                    double anchorWeight = dragonTransitioning
                        ? 1.0 - dragonLandingMatchFraction() : 1.0;
                    riderForward += (int) Math.round(flyingDragonRiderAnchor.forward * anchorWeight);
                    riderSideways += (int) Math.round(flyingDragonRiderAnchor.sideways * anchorWeight);
                    riderHeight += (int) Math.round(flyingDragonRiderAnchor.height * anchorWeight);
                }
                if (config.mountType() == MountType.TERRORBIRD && moving && terrorbirdRiderAnchor.moving)
                {
                    riderForward += terrorbirdRiderAnchor.forward;
                    riderSideways += terrorbirdRiderAnchor.sideways;
                    riderHeight += terrorbirdRiderAnchor.height;
                }
                if (config.mountType() != MountType.BLACK_UNICORN
                    && config.mountType() != MountType.GRYPHON
                    && config.mountType() != MountType.FLYING_DRAGON
                    && !(config.mountType() == MountType.TERRORBIRD && terrorbirdRiderAnchor.moving) && moving)
                {
                    riderForward += currentWalkForwardAdjustment();
                    riderForward += currentSeatSway();
                    riderSideways += currentLateralSway();
                    riderHeight += currentWalkHeightAdjustment();
                    riderHeight += currentStrideFollow();
                    riderHeight += currentSeatBounce();
                }
                else if (config.mountType() != MountType.BLACK_UNICORN
                    && config.mountType() != MountType.GRYPHON
                    && config.mountType() != MountType.FLYING_DRAGON
                    && !moving)
                {
                    riderHeight += currentIdleBounce();
                }
                LocalPoint riderPoint = offsetFromPlayer(
                    config.mountType() == MountType.TZREK_ZUK ? mountPoint : playerPoint,
                    orientation,
                    riderForward,
                    riderSideways);
                rider.setLocation(riderPoint, plane);
                rider.setZ(Perspective.getTileHeight(client, riderPoint, plane) - riderHeight);
                rider.setOrientation(orientation);
                boolean twoHandReadyPose = terrorbirdAttackAnimation < 0
                    && manualBattleReady && player.getIdlePoseAnimation() >= 0
                    && useTerrorbirdTwoHandReadyPose(player);
                boolean oneHandReadyPose = terrorbirdAttackAnimation < 0
                    && terrorbirdCombatActive
                    && !twoHandReadyPose
                    && (manualBattleReady || useTerrorbirdOneHandReadyPose(player));
                int combatUpperAnimation = terrorbirdAttackAnimation >= 0
                    ? terrorbirdAttackAnimation
                    : oneHandReadyPose
                        ? TERRORBIRD_ONE_HAND_READY_ANIMATION
                        : twoHandReadyPose
                            ? player.getIdlePoseAnimation()
                            : terrorbirdHeldCombatAnimation;
                boolean splitCombatRider = terrorbirdCombatActive
                    && combatUpperAnimation >= 0
                    && terrorbirdLowerModel != null && terrorbirdUpperModel != null
                    && terrorbirdUpperRider != null;
                if (splitCombatRider != terrorbirdSplitVisible)
                {
                    rider.setModel(splitCombatRider ? terrorbirdLowerModel : builtRiderModel);
                    terrorbirdSplitVisible = splitCombatRider;
                }
                if (splitCombatRider)
                {
                    // Keep both rider pieces on the same scene tile. Offsetting
                    // the upper object's location can send it across a tile
                    // boundary and make only the torso disappear there.
                    terrorbirdUpperRider.setLocation(riderPoint, plane);
                    terrorbirdUpperRider.setZ(
                        Perspective.getTileHeight(client, riderPoint, plane) - riderHeight
                            + TERRORBIRD_COMBAT_UPPER_OVERLAP);
                    terrorbirdUpperRider.setOrientation(orientation);
                }

                if (mountedHolsterActive && !terrorbirdCombatActive)
                {
                    mountedHolsterRenderer.refresh(player, riderPoint, plane,
                        orientation, Perspective.getTileHeight(client, riderPoint, plane) - riderHeight,
                        mountedHolsterSideways(), mountedHolsterHeight(), mountedHolsterForward());
                }
                else
                {
                    mountedHolsterRenderer.clear();
                }

                if (config.ridingPose() != null)
                {
                    boolean widePose = config.ridingPose() == RidingPose.WIDE;
                    boolean extraWidePose = config.ridingPose().usesExtraWideAnimation();
                    boolean crossLeggedPose = config.ridingPose() == RidingPose.CROSS_LEGGED;
                    int wantedRiderAnimation = crossLeggedPose
                        ? config.crossLeggedAnimationId()
                        : widePose
                            ? WIDE_RIDER_ANIMATION_ID
                            : extraWidePose
                                ? (moving
                                    ? config.extraWideWalkAnimationId()
                                    : config.extraWideIdleAnimationId())
                                : RIDER_ANIMATION_ID;
                    int wantedRiderFrame = widePose ? WIDE_RIDER_FRAME : -1;
                    int playerAttackFrame = terrorbirdAttackAnimation >= 0
                        ? player.getAnimationFrame() : -1;
                    boolean restartedAttack = playerAttackFrame >= 0
                        && (lastTerrorbirdAttackFrame < 0
                            || playerAttackFrame < lastTerrorbirdAttackFrame);
                    if (wantedRiderAnimation != activeRiderAnimation
                        || wantedRiderFrame != activeRiderFrame)
                    {
                        AnimationController controller = widePose
                            ? frozenAnimation(wantedRiderAnimation, wantedRiderFrame)
                            : crossLeggedPose
                                ? tailLoopAnimation(
                                    wantedRiderAnimation,
                                    config.crossLeggedLoopStartFrame(),
                                    config.crossLeggedLoopEndFrame())
                                : loopingAnimation(wantedRiderAnimation);
                        rider.setAnimationController(controller);
                        activeRiderAnimation = wantedRiderAnimation;
                        activeRiderFrame = wantedRiderFrame;
                    }
                    if (splitCombatRider)
                    {
                        if (activeTerrorbirdUpperAnimation != combatUpperAnimation
                            || activeTerrorbirdUpperReadyPose != oneHandReadyPose
                            || activeTerrorbirdUpperTwoHandReadyPose != twoHandReadyPose
                            || restartedAttack)
                        {
                            AnimationController upperAttack;
                            if (oneHandReadyPose)
                            {
                                Animation readyAnimation = client.loadAnimation(combatUpperAnimation);
                                if (readyAnimation == null)
                                {
                                    upperAttack = null;
                                }
                                else
                                {
                                    int lastFrame = (readyAnimation.isMayaAnim()
                                        ? readyAnimation.getDuration() : readyAnimation.getNumFrames()) - 1;
                                    upperAttack = frozenAnimation(combatUpperAnimation, lastFrame);
                                }
                            }
                            else if (twoHandReadyPose)
                            {
                                upperAttack = loopingAnimation(combatUpperAnimation);
                            }
                            else
                            {
                                upperAttack = new AnimationController(client, combatUpperAnimation);
                                upperAttack.setOnFinished(finished ->
                                {
                                    if (finished.getAnimation() != null)
                                    {
                                        finished.setFrame(Math.max(0,
                                            finished.getAnimation().getNumFrames() - 1));
                                    }
                                });
                            }
                            // Seed the controller once if combat was detected after
                            // frame zero, then let it advance itself. Reapplying the
                            // actor's integer frame every render prevents RuneLite's
                            // animation interpolation and makes the torso judder.
                            if (upperAttack != null && !oneHandReadyPose && playerAttackFrame > 0)
                            {
                                upperAttack.setFrame(playerAttackFrame);
                            }
                            terrorbirdUpperRider.setAnimationController(upperAttack);
                            activeTerrorbirdUpperAnimation = combatUpperAnimation;
                            activeTerrorbirdUpperReadyPose = oneHandReadyPose;
                            activeTerrorbirdUpperTwoHandReadyPose = twoHandReadyPose;
                        }
                    }
                    else
                    {
                        activeTerrorbirdUpperAnimation = -1;
                        activeTerrorbirdUpperReadyPose = false;
                        activeTerrorbirdUpperTwoHandReadyPose = false;
                    }
                    lastTerrorbirdAttackFrame = playerAttackFrame;
                }
                else if (activeRiderAnimation != -1)
                {
                    rider.setAnimationController(null);
                    activeRiderAnimation = -1;
                    activeRiderFrame = -1;
                }
                riderReady = true;
            }
        }

        activate(unicorn);
        for (RuneLiteObject part : mountParts)
        {
            activate(part);
        }
        // Reserve the rider before optional Artio accessories are activated.
        // This keeps the rider visible when changing Artio's scale forces all
        // RuneLite objects to be rebuilt on the same tile.
        if (riderReady)
        {
            activate(rider);
            if (terrorbirdSplitVisible)
            {
                activate(terrorbirdUpperRider);
            }
            else
            {
                deactivate(terrorbirdUpperRider);
            }
            mountedRenderReady = unicorn.isActive() && rider.isActive();
        }
        else
        {
            deactivate(rider);
            deactivate(terrorbirdUpperRider);
            mountedRenderReady = false;
        }
        if (!mountedRenderReady && mountedHolsterRenderer != null)
        {
            mountedHolsterRenderer.clear();
        }
        setHolsterHandoff(mountedHolsterActive);
        // Fitted tack is automatic for each approved mount/style combination.
        if ((config.mountType() == MountType.BLACK_UNICORN
                && isWidePose())
            || config.mountType() == MountType.TERRORBIRD
            || (config.mountType() == MountType.GRYPHON
                && config.ridingPose() == RidingPose.STANDARD)
            || (config.mountType() == MountType.BATTLE_TURTLE
                && isCrossLeggedPose())
            || (config.mountType() == MountType.ARTIO
                && !isNoSaddlePose()))
        {
            activate(saddle);
            if (config.mountType() == MountType.TERRORBIRD)
            {
                // The split combat rider needs two independent objects. Give
                // both rider halves priority over the optional rein mesh on
                // crowded tiles; the saddle itself remains visible.
                if (!terrorbirdSplitVisible && lastTerrorbirdReinAnchors != null)
                {
                    activate(terrorbirdReins);
                }
                else
                {
                    deactivate(terrorbirdReins);
                }
            }
            if (config.mountType() == MountType.ARTIO)
            {
                if (!isExtraWidePose())
                {
                    activate(artioShield);
                }
                else
                {
                    deactivate(artioShield);
                }
                activate(artioWarspears);
            }
        }
        else
        {
            deactivate(saddle);
            deactivate(terrorbirdReins);
            deactivate(artioShield);
            deactivate(artioWarspears);
        }
    }

    private boolean useTerrorbirdOneHandReadyPose(Player player)
    {
        if (player.getPlayerComposition() == null)
        {
            return false;
        }

        Outfit equipment = Outfit.from(player.getPlayerComposition());
        if (equipment.isItem(KitType.SHIELD))
        {
            return true;
        }
        if (!equipment.isItem(KitType.WEAPON))
        {
            return false;
        }

        ItemStats weapon = itemManager.getItemStats(equipment.itemId(KitType.WEAPON));
        return weapon != null && weapon.getEquipment() != null
            && weapon.getEquipment().getSlot() == KitType.WEAPON.getIndex()
            && !weapon.getEquipment().isTwoHanded();
    }

    private boolean useTerrorbirdTwoHandReadyPose(Player player)
    {
        if (player.getPlayerComposition() == null)
        {
            return false;
        }

        Outfit equipment = Outfit.from(player.getPlayerComposition());
        if (!equipment.isItem(KitType.WEAPON) || equipment.isItem(KitType.SHIELD))
        {
            return false;
        }
        ItemStats weapon = itemManager.getItemStats(equipment.itemId(KitType.WEAPON));
        return weapon != null && weapon.getEquipment() != null
            && weapon.getEquipment().isTwoHanded();
    }

    private Model buildRiderModel(Player player)
    {
        if (player.getPlayerComposition() == null)
        {
            return null;
        }

        if (!modelRepository.isLoaded())
        {
            modelRepository.loadFromClient(client);
            if (!modelRepository.isLoaded())
            {
                return null;
            }
        }

        Outfit currentOutfit = Outfit.from(player.getPlayerComposition());
        // Follower Buddy and similar appearance plugins can recolour the live
        // player without changing PlayerComposition#getColors(). Read the skin
        // replacement from that live model before hiding held gear for riding.
        Model livePlayerModel = player.getModel();
        if (livePlayerModel != null && livePlayerModel.getFaceColors1() != null)
        {
            int skinSignature = java.util.Arrays.hashCode(livePlayerModel.getFaceColors1());
            if (skinSignature != lastLiveSkinSignature
                || !currentOutfit.equals(lastLiveSkinOutfit))
            {
                appearanceComposer.setLiveSkinColor(
                    appearanceComposer.detectLiveSkinColor(currentOutfit, livePlayerModel));
                lastLiveSkinSignature = skinSignature;
                lastLiveSkinOutfit = Outfit.from(player.getPlayerComposition());
                builtRiderModel = null;
            }
        }
        if (config.hideHeldEquipment() && !terrorbirdCombatActive)
        {
            currentOutfit.clear(KitType.WEAPON);
            currentOutfit.clear(KitType.SHIELD);
        }
        if (config.hideCape())
        {
            currentOutfit.clear(KitType.CAPE);
        }
        appearanceComposer.setCapeAdjustment(
            config.capeHeightOffset(),
            config.capeBackwardOffset());
        if (builtRiderModel == null || !currentOutfit.equals(builtRiderOutfit))
        {
            builtRiderModel = appearanceComposer.compose(currentOutfit);
            if (config.mountType() == MountType.TERRORBIRD && terrorbirdUpperRider != null)
            {
                terrorbirdLowerModel = appearanceComposer.composeSelected(currentOutfit,
                    java.util.EnumSet.of(KitType.LEGS, KitType.BOOTS));
                terrorbirdUpperModel = appearanceComposer.composeSelected(currentOutfit,
                    java.util.EnumSet.complementOf(java.util.EnumSet.of(KitType.LEGS, KitType.BOOTS)));
                if (terrorbirdUpperModel != null)
                {
                    terrorbirdUpperRider.setModel(terrorbirdUpperModel);
                }
            }
            builtRiderOutfit = builtRiderModel == null ? null : currentOutfit;
            if (builtRiderModel != null)
            {
                rider.setModel(builtRiderModel);
            }
            rider.setAnimationController(null);
            activeRiderAnimation = -1;
            activeRiderFrame = -1;
            terrorbirdSplitVisible = false;
        }
        return builtRiderModel;
    }

    private boolean ensureObjects()
    {
        if (unicorn != null
            && rider != null
            && builtMountType == config.mountType()
            && builtScale == currentMountScale()
            && builtSaddleScale == currentSaddleBuildScale())
        {
            return true;
        }

        despawn();
        List<Model> separateModels = null;
        Model unicornModel = (config.mountType() == MountType.GRYPHON
            || config.mountType() == MountType.ARTIO)
            ? buildUnscaledPostScaleMountModel()
            : buildMountModel();
        if (unicornModel == null)
        {
            return false;
        }

        unicorn = client.createRuneLiteObject();
        rider = client.createRuneLiteObject();
        if (unicorn == null || rider == null)
        {
            despawn();
            return false;
        }

        if (config.mountType() == MountType.TERRORBIRD)
        {
            terrorbirdUpperRider = client.createRuneLiteObject();
            if (terrorbirdUpperRider == null)
            {
                despawn();
                return false;
            }
            terrorbirdUpperRider.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
            terrorbirdUpperRider.setDrawFrontTilesFirst(true);
        }

        unicorn.setModel(unicornModel);
        unicorn.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
        unicorn.setDrawFrontTilesFirst(true);

        if (config.mountType() == MountType.BLACK_UNICORN)
        {
            Model saddleModel;
            if (config.useCustomSaddle())
            {
                // The live unicorn mouth anchors rebuild the reins from the
                // actual animated model, so a synthetic frame cache is no
                // longer needed.
                saddleMotionModels = null;
                saddleModel = buildCustomSaddleModel(0);
                activeSaddleMotionFrame = -1;
            }
            else
            {
                saddleModel = buildSaddlePrototypeModel();
            }
            if (saddleModel != null)
            {
                saddle = client.createRuneLiteObject();
                if (saddle == null)
                {
                    despawn();
                    return false;
                }
                saddle.setModel(saddleModel);
                saddle.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
                saddle.setDrawFrontTilesFirst(true);
            }
        }
        else if (config.mountType() == MountType.TERRORBIRD)
        {
            Model saddleModel = buildTerrorbirdSaddleModel();
            if (saddleModel != null)
            {
                saddle = client.createRuneLiteObject();
                if (saddle == null)
                {
                    despawn();
                    return false;
                }
                saddle.setModel(saddleModel);
                saddle.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
                saddle.setDrawFrontTilesFirst(true);
                // Keep the seat's model stable while only the animated reins
                // receive replacement meshes during walking.
                terrorbirdReins = client.createRuneLiteObject();
                if (terrorbirdReins != null)
                {
                    terrorbirdReins.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
                    terrorbirdReins.setDrawFrontTilesFirst(true);
                }
            }
        }
        else if (config.mountType() == MountType.GRYPHON)
        {
            Model saddleModel = buildGryphonSaddleModel(null, null);
            if (saddleModel != null)
            {
                saddle = client.createRuneLiteObject();
                if (saddle == null)
                {
                    despawn();
                    return false;
                }
                saddle.setModel(saddleModel);
                saddle.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
                saddle.setDrawFrontTilesFirst(true);
            }
        }
        else if (config.mountType() == MountType.BATTLE_TURTLE)
        {
            Model saddleModel = buildBattleTurtleSaddleModel();
            if (saddleModel != null)
            {
                saddle = client.createRuneLiteObject();
                if (saddle == null)
                {
                    despawn();
                    return false;
                }
                saddle.setModel(saddleModel);
                saddle.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
                saddle.setDrawFrontTilesFirst(true);
            }
        }
        else if (config.mountType() == MountType.ARTIO)
        {
            Model saddleModel = buildArtioArmourModel(null, null);
            if (saddleModel != null)
            {
                saddle = client.createRuneLiteObject();
                if (saddle == null)
                {
                    despawn();
                    return false;
                }
                saddle.setModel(saddleModel);
                saddle.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
                saddle.setDrawFrontTilesFirst(true);

                // Cache-backed equipment is kept as a separate object. Some
                // cache models cannot be safely merged with the procedural
                // saddle and would otherwise make the entire saddle vanish.
                try
                {
                    // ensureObjects builds tack before buildRiderModel, which
                    // normally initialises this catalogue. Load it here first
                    // so the shield's worn model is available on initial spawn.
                    if (!modelRepository.isLoaded())
                    {
                        modelRepository.loadFromClient(client);
                    }
                    int scale = Math.max(1, 128 * config.artioArmourScale() / 100);
                    ModelData shieldData = isExtraWidePose()
                        ? null
                        : buildMountedVsShield(null, scale);
                    if (shieldData != null)
                    {
                        artioShield = client.createRuneLiteObject();
                        if (artioShield != null)
                        {
                            artioShield.setModel(shieldData.light(
                                AMBIENT, CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z));
                            artioShield.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
                            artioShield.setDrawFrontTilesFirst(true);
                        }
                    }
                    artioWarspears = createArtioWarspears(null, scale);
                }
                catch (RuntimeException ignored)
                {
                    artioShield = null;
                }
            }
        }

        if (separateModels != null)
        {
            for (int i = 1; i < separateModels.size(); i++)
            {
                RuneLiteObject part = client.createRuneLiteObject();
                if (part == null)
                {
                    despawn();
                    return false;
                }
                part.setModel(separateModels.get(i));
                part.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
                part.setDrawFrontTilesFirst(true);
                mountParts.add(part);
            }
        }

        rider.setRenderMode(Renderable.RENDERMODE_SORTED_NO_DEPTH);
        rider.setDrawFrontTilesFirst(true);

        builtMountType = config.mountType();
        builtScale = currentMountScale();
        builtSaddleScale = currentSaddleBuildScale();
        activeUnicornAnimation = -1;
        activeRiderAnimation = -1;
        return true;
    }

    private Model buildSaddlePrototypeModel()
    {
        if (config.useCustomSaddle())
        {
            return buildCustomSaddleModel(0);
        }

        int sourceNpcId;
        switch (config.saddleSource())
        {
            case BANK_BUFFALO:
                sourceNpcId = config.bankBuffaloNpcId() > 0
                    ? config.bankBuffaloNpcId()
                    : BANK_BUFFALO_NPC_ID;
                break;
            case CART_CAMEL:
                sourceNpcId = config.cartCamelNpcId() > 0
                    ? config.cartCamelNpcId()
                    : CART_CAMEL_NPC_ID;
                break;
            case MOUNTED_TERRORBIRD:
            default:
                sourceNpcId = SADDLE_SOURCE_NPC_ID;
                break;
        }
        if (sourceNpcId <= 0)
        {
            return null;
        }

        NPCComposition composition = client.getNpcDefinition(sourceNpcId);
        if (composition != null && composition.getConfigs() != null)
        {
            NPCComposition transformed = composition.transform();
            if (transformed != null)
            {
                composition = transformed;
            }
        }
        int[] ids = composition == null ? null : composition.getModels();
        int part = config.saddleSourcePart();
        if (ids == null || ids.length == 0 || part >= ids.length)
        {
            return null;
        }

        ModelData data;
        if (part == -1)
        {
            ModelData[] loaded = new ModelData[ids.length];
            int count = 0;
            for (int id : ids)
            {
                ModelData modelPart = client.loadModelData(id);
                if (modelPart != null)
                {
                    loaded[count++] = modelPart;
                }
            }
            if (count == 0)
            {
                return null;
            }
            if (count != loaded.length)
            {
                ModelData[] available = new ModelData[count];
                System.arraycopy(loaded, 0, available, 0, count);
                loaded = available;
            }
            data = count == 1 ? loaded[0] : client.mergeModels(loaded);
        }
        else
        {
            data = client.loadModelData(ids[part]);
        }
        if (data == null)
        {
            return null;
        }
        if (composition.getColorToReplace() != null
            && composition.getColorToReplaceWith() != null)
        {
            data = data.cloneColors();
            short[] from = composition.getColorToReplace();
            short[] to = composition.getColorToReplaceWith();
            for (int i = 0; i < Math.min(from.length, to.length); i++)
            {
                data.recolor(from[i], to[i]);
            }
        }
        data = data.cloneVertices();
        int scale = Math.max(1, 128 * config.saddleScale() / 100);
        data.scale(scale, scale, scale);
        return data.light(AMBIENT, CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z);
    }

    private Model buildCustomSaddleModel(int motionFrame)
    {
        return buildCustomSaddleModel(motionFrame, null);
    }

    private Model buildCustomSaddleModel(int motionFrame, int[] reinAnchors)
    {
        ModelData template = client.loadModelData(FALLBACK_BODY_MODEL);
        if (template == null)
        {
            return null;
        }

        ModelData data = client.mergeModels(new ModelData[]{
            template,
            template.shallowCopy(),
            template.shallowCopy(),
            template.shallowCopy()
        });
        if (data == null || data.getVerticesCount() < 128 || data.getFaceCount() < 204)
        {
            return null;
        }

        data = data.cloneVertices().cloneColors();
        float[] x = data.getVerticesX();
        float[] y = data.getVerticesY();
        float[] z = data.getVerticesZ();
        int[] face1 = data.getFaceIndices1();
        int[] face2 = data.getFaceIndices2();
        int[] face3 = data.getFaceIndices3();
        short[] colors = data.getFaceColors();

        for (int i = 0; i < x.length; i++)
        {
            x[i] = 0;
            y[i] = 0;
            z[i] = 0;
        }
        for (int i = 0; i < face1.length; i++)
        {
            face1[i] = 0;
            face2[i] = 0;
            face3[i] = 0;
            colors[i] = 0;
        }

        final short clothRed = (short) 931;
        final short saddleBlack = (short) 13;
        final short blackHighlight = (short) 21;
        final short steelGrey = (short) 72;

        int vertex = 0;
        int face = 0;

        face = addSaddleArch(x, y, z, face1, face2, face3, colors,
            vertex, face,
            new int[]{-38, -30, 0, 30, 38},
            new int[]{17, 1, -10, 1, 17},
            new int[]{23, 7, -4, 7, 23},
            -41, 39, clothRed);
        vertex += 20;
        face = addSaddleArch(x, y, z, face1, face2, face3, colors,
            vertex, face,
            new int[]{-28, -22, 0, 22, 28},
            new int[]{4, -12, -22, -12, 4},
            new int[]{9, -6, -15, -6, 9},
            -32, 28, saddleBlack);
        vertex += 20;
        face = addSaddleBox(x, y, z, face1, face2, face3, colors,
            vertex, face, -17, 17, -25, -15, 20, 29, blackHighlight);
        vertex += 8;
        face = addSaddleBox(x, y, z, face1, face2, face3, colors,
            vertex, face, -21, 21, -24, -15, -33, -25, blackHighlight);
        vertex += 8;
        face = addSaddleBox(x, y, z, face1, face2, face3, colors,
            vertex, face, -39, -34, 12, 31, -7, 8, steelGrey);
        vertex += 8;
        face = addSaddleBox(x, y, z, face1, face2, face3, colors,
            vertex, face, 34, 39, 12, 31, -7, 8, steelGrey);
        vertex += 8;

        // Twin segmented reins. The three short sections on each side create a
        // deliberate low-poly curve from the pommel towards the unicorn's bit.
        int reinLength = config.reinLength();
        int reinEndHeight = config.reinEndHeight();
        int reinSpread = config.reinSpread();
        double reinMotionScale = config.reinMotionSizePercent() / 100.0;
        int reinHeightProfile;
        int reinForwardProfile;
        int regularFrames = REIN_LOOP_FRAMES * REIN_REGULAR_LOOPS;
        if (motionFrame < regularFrames)
        {
            int loopFrame = motionFrame % REIN_LOOP_FRAMES;
            reinHeightProfile = UNICORN_REIN_HEIGHT_PROFILE[loopFrame];
            reinForwardProfile = UNICORN_REIN_FORWARD_PROFILE[loopFrame];
        }
        else
        {
            // After four regular motions the source idle animation performs a
            // pronounced bow. Follow it as its own eased down-and-up section.
            double bowProgress = (motionFrame - regularFrames)
                / (double) (REIN_LOOP_FRAMES - 1);
            double bowAmount = Math.sin(Math.PI * bowProgress);
            // RuneLite model Y increases downwards here: follow the muzzle
            // down during the bow instead of lifting the bit through it.
            reinHeightProfile = (int) Math.round(350.0 * bowAmount);
            reinForwardProfile = (int) Math.round(85.0 + 150.0 * bowAmount);
        }
        int reinHeadHeightMotion = (int) Math.round(
            config.reinHeadBob() * reinMotionScale * reinHeightProfile / 100.0);
        int reinHeadForwardMotion = (int) Math.round(
            config.reinHeadSway() * reinMotionScale * reinForwardProfile / 100.0);
        if (motionFrame >= regularFrames)
        {
            // The final part of the unicorn idle is a full neck-driven bow,
            // not another small head bob. Do not attenuate this displacement
            // with the user's fine-motion percentage: doing so leaves the bit
            // almost stationary while the muzzle travels through it.
            double bowProgress = (motionFrame - regularFrames)
                / (double) (REIN_LOOP_FRAMES - 1);
            double bowAmount;
            final double bowPeak = 0.33;
            if (bowProgress <= bowPeak)
            {
                // Reach the confirmed mouth position slightly earlier so the
                // return begins with the unicorn's upward head movement.
                bowAmount = Math.sin(
                    bowProgress / bowPeak * Math.PI / 2.0);
            }
            else
            {
                // Complete the return another 20% faster than the previous
                // tuned return, then hold at rest. This lets the
                // bit follow the unicorn's quicker upward head movement.
                double returnProgress = (bowProgress - bowPeak)
                    / (0.32 / 1.2 / 1.2 / 1.2);
                bowAmount = returnProgress >= 1.0
                    ? 0.0
                    : Math.cos(returnProgress * Math.PI / 2.0);
            }
            reinHeadHeightMotion = (int) Math.round(27.2 * bowAmount);
            // Negative model Z extends the mouth end away from the rider.
            // Follow the bow forwards towards the dipping muzzle instead of
            // pulling the bit backwards into the unicorn's neck and body.
            reinHeadForwardMotion = (int) Math.round(-5.6 * bowAmount);
        }
        int[][][] reinPaths;
        int[][] mouthEnds = null;
        if (reinAnchors != null && reinAnchors.length == 6)
        {
            mouthEnds = new int[][]{
                {reinAnchors[0], reinAnchors[1], reinAnchors[2]},
                {reinAnchors[3], reinAnchors[4], reinAnchors[5]}
            };
            int[][] handEnds =
            {
                {-16 + config.leftReinHandSideways(),
                    -18 - config.leftReinHandHeight(),
                    -25 - config.leftReinHandForward()},
                {16 + config.rightReinHandSideways(),
                    -18 - config.rightReinHandHeight(),
                    -25 - config.rightReinHandForward()}
            };
            reinPaths = new int[2][][];
            for (int side = 0; side < 2; side++)
            {
                int[] hand = handEnds[side];
                int[] mouth = mouthEnds[side];
                int outward = side == 0 ? -24 : 24;
                int[] control1 = {
                    hand[0] + (mouth[0] - hand[0]) / 3 + outward,
                    hand[1] + (mouth[1] - hand[1]) / 3 + 8,
                    hand[2] + (mouth[2] - hand[2]) / 3
                };
                int[] control2 = {
                    mouth[0] + (hand[0] - mouth[0]) / 4 + outward,
                    mouth[1] + 16,
                    mouth[2] + (hand[2] - mouth[2]) / 5
                };
                reinPaths[side] = buildCubicReinPath(
                    hand, control1, control2, mouth, 4);
            }
        }
        else
        {
            reinPaths = new int[][][]{
                buildReinPath(-1, reinLength, reinEndHeight, reinSpread,
                    reinHeadHeightMotion, reinHeadForwardMotion,
                    config.leftReinHandForward(), config.leftReinHandHeight(),
                    config.leftReinHandSideways()),
                buildReinPath(1, reinLength, reinEndHeight, reinSpread,
                    reinHeadHeightMotion, reinHeadForwardMotion,
                    config.rightReinHandForward(), config.rightReinHandHeight(),
                    config.rightReinHandSideways())
            };
        }
        for (int[][] reinPath : reinPaths)
        {
            for (int i = 0; i < reinPath.length - 1; i++)
            {
                int[] from = reinPath[i];
                int[] to = reinPath[i + 1];
                face = addSaddleStrap(x, y, z, face1, face2, face3, colors,
                    vertex, face,
                    from[0], from[1], from[2],
                    to[0], to[1], to[2],
                    2, 1, clothRed);
                vertex += 8;
            }
        }

        // Steel-grey bit across the mouth, joining the two rein endpoints.
        int bitHalfWidth = mouthEnds == null
            ? Math.max(2, 11 + reinSpread) + 6
            : Math.max(Math.abs(mouthEnds[0][0]), Math.abs(mouthEnds[1][0])) + 6;
        int bitY = mouthEnds == null
            ? -47 + reinEndHeight + reinHeadHeightMotion
            : (mouthEnds[0][1] + mouthEnds[1][1]) / 2;
        int bitZ = mouthEnds == null
            ? -reinLength + reinHeadForwardMotion
            : (mouthEnds[0][2] + mouthEnds[1][2]) / 2;
        addSaddleBox(x, y, z, face1, face2, face3, colors,
            vertex, face,
            -bitHalfWidth, bitHalfWidth,
            bitY - 2, bitY + 2,
            bitZ - 3, bitZ + 3,
            steelGrey);

        int scale = Math.max(1, 128 * config.saddleScale() / 100);
        data.scale(scale, scale, scale);
        return data.light(AMBIENT, CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z);
    }

