            vertex, face, -10, 10, -91, -81, 27, 35, brass);
        vertex += 8;

        // Layered flank armour makes the platform read as a battle saddle.
        int[][] armourPlates =
        {
            {-76, -60, -27, 15, -31, 31},
            {-82, -70, -18, 24, -20, 20},
            {-86, -76, -9, 31, -10, 10},
            {60, 76, -27, 15, -31, 31},
            {70, 82, -18, 24, -20, 20},
            {76, 86, -9, 31, -10, 10}
        };
        for (int i = 0; i < armourPlates.length; i++)
        {
