        for (int i = 0; i < 5; i++)
        {
            int next = (i + 1) % 5;
            face = addSaddleTriangle(face1, face2, face3, colors, face,
                vertex + i, vertex + next, vertex + 5 + next, color);
            face = addSaddleTriangle(face1, face2, face3, colors, face,
